type launchCloud struct {
	Cloud
	launched []string // display names
	tokens   []string
	reads    map[string]int
	details  map[string]core.LaunchInstanceDetails // by instance ID
	unlisted bool                                  // ListInstances lags the launches
}

func (c *launchCloud) LaunchInstance(_ context.Context, details core.LaunchInstanceDetails, token string) (core.Instance, string, error) {
	c.launched, c.tokens = append(c.launched, *details.DisplayName), append(c.tokens, token)
	id := "ocid1.instance.oc1..i-" + *details.DisplayName
	if c.details == nil {
		c.details = map[string]core.LaunchInstanceDetails{}
	}
	c.details[id] = details
	return core.Instance{Id: &id, DisplayName: details.DisplayName}, "ocid1.workrequest.oc1..w", nil
}
func (c *launchCloud) ListInstances(context.Context, string) ([]Instance, error) {
	if c.unlisted {
		return nil, nil
	}
	var instances []Instance
	for _, name := range c.launched {
		instances = append(instances, Instance{ID: "ocid1.instance.oc1..i-" + name, DisplayName: name, LifecycleState: "RUNNING"})
	}
	return instances, nil
}

// GetInstance reports the instance as OCI would after the recorded launch.
func (c *launchCloud) GetInstance(_ context.Context, id string) (Instance, error) {
	if c.reads == nil {
		c.reads = map[string]int{}
	}
	d := c.details[id]
	launched := Instance{ID: id, LifecycleState: "RUNNING", DisplayName: deref(d.DisplayName), CompartmentID: deref(d.CompartmentId),
		AvailabilityDomain: deref(d.AvailabilityDomain), FaultDomain: deref(d.FaultDomain), Shape: deref(d.Shape),
		Metadata: d.Metadata, FreeformTags: d.FreeformTags}
	if d.ShapeConfig != nil {
		launched.OCPUs, launched.MemoryInGBs = *d.ShapeConfig.Ocpus, *d.ShapeConfig.MemoryInGBs
	}
	if source, ok := d.SourceDetails.(core.InstanceSourceViaImageDetails); ok {
		launched.ImageID = deref(source.ImageId)
	}
	if c.reads[id]++; c.reads[id] == 1 {
		launched.LifecycleState = "PROVISIONING"
	}
	return launched, nil
}

func flagValue(args []string, name string) string {
	if i := slices.Index(args, name); i >= 0 && i+1 < len(args) {
		return args[i+1]
	}
	return ""
}

// cellAttempt is an attempt over the repository plan whose previews write
// their outputs; admissionLeft is the cost admission lifetime it reports.
func cellAttempt(t *testing.T, admissionLeft time.Duration, launch string) (*Attempt, *launchCloud, *[][]string) {
	t.Helper()
	a := smallAttempt(t)
	now := time.Date(2026, 10, 4, 12, 0, 0, 0, time.UTC)
	a.Now = func() time.Time { return now }
	a.Sleep = func(context.Context, time.Duration) error { return nil }
	plan, err := os.ReadFile("../../deploy/oci-region/plan.json")
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(a.Plan(), plan, 0600); err != nil {
		t.Fatal(err)
	}
	a.writeJSON(a.Path("image", "import.json"), Object{"image_id": "ocid1.image.fixture"})
	cloud := &launchCloud{}
	a.Cloud = cloud
	var commands [][]string
	a.Runner = func(_ context.Context, c Command) (string, error) {
		commands = append(commands, c.Args)
		out := flagValue(c.Args, "--out")
		switch {
		case slices.Contains(c.Args, "inventory"):
			return "", os.WriteFile(out, []byte("{}"), 0600)
		case slices.Contains(c.Args, "admit"):
			return "", os.WriteFile(out, []byte(`{"expires_at":"`+now.Add(admissionLeft).Format(time.RFC3339Nano)+`"}`), 0600)
		case slices.Contains(c.Args, "member-launch"):
			name := map[string]string{"member-a": "gru-1-db-1", "member-b": "gru-1-db-2"}[flagValue(c.Args, "--slot")]
			return "", os.WriteFile(out, []byte(strings.Replace(launch, "gru-1-ctl-1", name, 1)), 0600)
		}
		return "", nil
	}
	if a.Err() != nil {
		t.Fatal(a.Err())
	}
	return a, cloud, &commands
}

func (a *Attempt) FreshAdmission(name string) (string, string) {
	inventory, admission := a.Path(name+"-inventory.json"), a.Path(name+"-admission.json")
	a.captureInventory(a.Plan(), inventory)
	a.preview("admit", "--plan", a.Plan(), "--inventory", inventory, "--out", admission)
	return inventory, admission
}

// captureInventory writes a live inventory of plan, trying the read three
// times.
func (a *Attempt) captureInventory(plan, inventory string) {
	if a.err != nil {
		return
	}
	command := Command{Args: []string{a.Executable, "oci-region", "preview", "inventory", "--plan", plan, "--out", inventory}, Dir: "/tmp", Env: a.Env}
	var e error
	for range 3 {
		_, e = a.Runner(a.ctx, command)
		if e == nil {
			break
		}
		if a.ctx.Err() != nil {
			break
		}
	}
	if e != nil {
		a.fail(fmt.Errorf("live inventory failed three times: %w", e))
	}
}

func (a *Attempt) bindSeed() {
	b, e := os.ReadFile(a.Path("launch", "controller-a.ocid"))
	if a.err != nil || errors.Is(e, os.ErrNotExist) {
		return
	}
	a.fail(e)
	plan := a.read(a.Plan())
	instances := object(object(plan["resource_ids"])["instances"])
	if a.err != nil || instances == nil {
		a.fail(fmt.Errorf("attempt plan has no instance bindings"))
		return
	}
	id := strings.TrimSpace(string(b))
	if bound, ok := instances["controller-a"].(string); ok && bound != id {
		a.fail(fmt.Errorf("attempt plan binds controller A %s, not the launched %s", bound, id))
		return
	}
	if instances["controller-a"] == id {
		return
	}
	instances["controller-a"] = id
	// The plan is otherwise write-once; this one recorded fact replaces it.
	wire, e := json.Marshal(plan, json.Deterministic(true))
	a.fail(e)
	temporary := a.Plan() + ".bind"
	if a.err == nil {
		a.fail(os.WriteFile(temporary, wire, 0600))
	}
	if a.err == nil {
		a.fail(os.Rename(temporary, a.Plan()))
	}
}

func (a *Attempt) requireAdmission(admission string) {
	expires, e := time.Parse(time.RFC3339Nano, str(a.read(admission), "expires_at"))
	a.fail(e)
	if expires.Sub(a.Now()) < 180*time.Second {
		a.fail(fmt.Errorf("cost admission has less than 180 seconds left"))
	}
}

// launchInstance submits the exact launch input, then records the CLI-shaped
// submit document and the instance ID.
func (a *Attempt) launchInstance(who string, details core.LaunchInstanceDetails, wire []byte, submit, ocid string) string {
	cloud := a.cloud("LaunchInstance")
	if cloud == nil {
		return ""
	}
	launched, workRequest, e := cloud.LaunchInstance(a.ctx, details, LaunchRetryToken(wire))
	a.fail(e)
	if a.err != nil {
		return ""
	}
	data, e := sdkcli.Render(launched)
	a.fail(e)
	var rendered any
	if a.err == nil {
		a.fail(json.Unmarshal(data, &rendered))
	}
	if a.err != nil {
		return ""
	}
	// The retained record keeps the CLI-shaped {"data": ...} document.
	submitted := Object{"data": rendered, "opc-work-request-id": workRequest}
	id := str(object(rendered), "id")
	if id == "" {
		a.fail(fmt.Errorf("%s launch omitted instance ID", who))
		return ""
	}
	a.writeJSON(submit, submitted)
	a.WriteNew(ocid, []byte(id+"\n"))
	fmt.Fprintln(a.Out, "launched", who, id)
	return id
}

// waitRunning polls an instance until it is RUNNING, 60 times 10 s apart.
func (a *Attempt) waitRunning(who, instance string) {
	// Announce the poll once; the seam is reused for every attempt.
	cloud := a.cloud("GetInstance (polling until RUNNING)")
	if cloud == nil {
		return
	}
	for range 60 {
		state, e := cloud.GetInstance(a.ctx, instance)
		a.fail(e)
		if a.err != nil || state.LifecycleState == "RUNNING" {
			return
		}
		a.fail(a.Sleep(a.ctx, 10*time.Second))
	}
	a.fail(fmt.Errorf("%s did not reach RUNNING", who))
}

func (a *Attempt) PhaseMembers() {
	launch := a.Path("launch")
	a.mkdir(launch)
	a.bindSeed()
	for _, v := range rows(a.read(a.Plan())["hosts"]) {
		slot := str(object(v), "slot")
		if !strings.HasPrefix(slot, "member-") {
			continue
		}
		name, e := naming.RegionCell(a.Cell().Cell).MemberSlot(slot)
		a.fail(e)
		if a.err != nil {
			return
		}
		ocid, launchInput := filepath.Join(launch, name+".ocid"), filepath.Join(launch, name+"-launch.json")
		var id string
		if exists(ocid) {
			b, e := os.ReadFile(ocid)
			a.fail(e)
			id = strings.TrimSpace(string(b))
			fmt.Fprintln(a.Out, name, "already launched:", id)
		} else if id = a.adoptMember(name, launchInput, ocid); a.err != nil {
			return
		} else if id != "" {
			fmt.Fprintln(a.Out, name, "was launched before its OCID was recorded:", id)
		} else {
			// An earlier input may be the record of a launch OCI has not listed
			// yet, which adoption needs: replace it only once a new input is
			// admitted and about to be launched.
			inventory, admission := a.FreshAdmission("launch/" + name)
			next := filepath.Join(launch, name+"-launch.next.json")
			a.remove(next)
			a.preview("member-launch", "--plan", a.Plan(), "--inventory", inventory, "--admission", admission, "--slot", slot, "--image-ocid", a.ImageID(), "--host-enrollment", a.Path("host-enrollment-public.json"), "--owner-ssh-public-key", str(a.Config, "owner_ssh_public_key"), "--out", next)
			if a.err != nil {
				return
			}
			wire, e := os.ReadFile(next)
			a.fail(e)
			if a.err != nil {
				return
			}
			details, e := LaunchDetails(wire)
			a.fail(e)
			a.release("verify-image-production", "--image-file", a.Path("image", "terrascale-arm64.qcow2"), "--qualification", a.Path("release", "qualification.json"), "--root-key", a.trust("root_public"), "--cell", a.Cell().Cell, "--environment", "canary", "--arch", "arm64", "--production-evidence-dir", a.Path("release", "image-production"), "--image-receipt", a.ImageReceipt(), "--delegation", a.Path("image", "image-delegation.signed.json"), "--image-ocid", a.ImageID())
			if a.requireAdmission(admission); a.err != nil {
				return
			}
			a.fail(os.Rename(next, launchInput))
			if a.err != nil {
				return
			}
			id = a.launchInstance(name, details, wire, filepath.Join(launch, name+"-launch-submit.json"), ocid)
		}
		// A resumed host may still be booting: wait for it either way.
		if a.waitRunning(name, id); a.err != nil {
			return
		}
	}
}

// adoptMember records the instance an interrupted members run launched
// before it wrote the OCID. It adopts the one live workload instance with
// the host's static name only when it is exactly the launch of this
// attempt's retained input, whose metadata carries this attempt's
// enrollment bundle; any other instance of the name needs reconciliation.
// member-launch refuses a name the inventory already holds.
func (a *Attempt) adoptMember(name, launchInput, ocid string) string {
	cloud := a.cloud("ListInstances workload_compartment")
	if cloud == nil {
		return ""
	}
	listed, e := cloud.ListInstances(a.ctx, str(object(a.read(a.Plan())["resource_ids"]), "workload_compartment"))
	a.fail(e)
	var ids []string
	for _, instance := range listed {
		if instance.DisplayName == name && instance.LifecycleState != "TERMINATED" && instance.LifecycleState != "TERMINATING" {
			ids = append(ids, instance.ID)
		}
	}
	if a.err != nil || len(ids) == 0 {
		return ""
	}
	wire, e := os.ReadFile(launchInput)
	if e != nil || len(ids) != 1 {
		a.fail(fmt.Errorf("%d live instances are named %s and this attempt has no single launch input for them; reconcile before retrying", len(ids), name))
		return ""
	}
	details, e := LaunchDetails(wire)
	a.fail(e)
	var launched Instance
	if a.err == nil {
		launched, e = cloud.GetInstance(a.ctx, ids[0])
		a.fail(e)
	}
	if a.err == nil && !launchedFrom(launched, details) {
		a.fail(fmt.Errorf("%s (%s) is not the launch of this attempt's %s; reconcile before retrying", name, ids[0], filepath.Base(launchInput)))
	}
	if a.err != nil {
		return ""
	}
	a.fail(a.WriteNew(ocid, []byte(ids[0]+"\n")))
	return ids[0]
}

func LaunchDetails(wire []byte) (core.LaunchInstanceDetails, error) {
	var input seedLaunch
	if err := json.Unmarshal(wire, &input, json.RejectUnknownMembers(true)); err != nil {
		return core.LaunchInstanceDetails{}, fmt.Errorf("decode controller launch input: %w", err)
	}
	source := input.SourceDetails
	if input.AvailabilityDomain == "" || input.FaultDomain == "" || input.CompartmentID == "" || input.DisplayName == "" ||
		input.Shape == "" || input.ShapeConfig.OCPUs <= 0 || input.ShapeConfig.MemoryInGBs <= 0 ||
		source.SourceType != "image" || source.ImageID == "" || source.BootVolumeSizeInGBs <= 0 || source.BootVolumeVpusPerGB <= 0 ||
		input.SubnetID == "" || input.PrivateIP == "" || len(input.NSGIDs) == 0 || input.AssignPublicIP == nil ||
		len(input.Metadata) == 0 || len(input.FreeformTags) == 0 {
		return core.LaunchInstanceDetails{}, errors.New("controller launch input lacks a required member")
	}
	return core.LaunchInstanceDetails{
		AvailabilityDomain: &input.AvailabilityDomain, FaultDomain: &input.FaultDomain, CompartmentId: &input.CompartmentID,
		DisplayName: &input.DisplayName, Shape: &input.Shape,
		ShapeConfig: &core.LaunchInstanceShapeConfigDetails{Ocpus: &input.ShapeConfig.OCPUs, MemoryInGBs: &input.ShapeConfig.MemoryInGBs},
		SourceDetails: core.InstanceSourceViaImageDetails{ImageId: &source.ImageID,
			BootVolumeSizeInGBs: &source.BootVolumeSizeInGBs, BootVolumeVpusPerGB: &source.BootVolumeVpusPerGB},
		CreateVnicDetails: &core.CreateVnicDetails{SubnetId: &input.SubnetID, PrivateIp: &input.PrivateIP,
			NsgIds: input.NSGIDs, AssignPublicIp: input.AssignPublicIP},
		Metadata: input.Metadata, FreeformTags: input.FreeformTags,
	}, nil
}

// LaunchRetryToken binds an OCI retry token to the exact launch input bytes.
func LaunchRetryToken(wire []byte) string {
	return entityid.Derive("attempt-launch", string(wire))
}

// Server roles.
const (
	Controller = "ctl"
	Member     = "db"
	Gateway    = "gw"
)

// ErrName reports a name outside the scheme.
var ErrName = errors.New("name does not follow ts-<region>-<n>[-data], <region>-<index>[-<role>-<n>[-data]] or <region>-<index>-pool-<pool>-<n>")

var scheme = regexp.MustCompile(`^([a-z]+)-[1-9][0-9]{0,2}(?:-(?:ctl|gw)-[1-9][0-9]{0,2}|-db-[1-9][0-9]{0,2}(?:-data)?|` +
	`-pool-[a-z][a-z0-9]{1,11}-[1-9][0-9]{0,2})?$`)

var nodeScheme = regexp.MustCompile(`^ts-([a-z]+)-[1-9][0-9]{0,2}(?:-data)?$`)

var apiPart = regexp.MustCompile(`^[a-z]+$`)

// Cell is one region's cell.
type Cell struct {
	Region string // catalog cell code, e.g. GRU
	Index  int
}

// RegionCell returns the cell a region runs. Every region runs one cell
// today, cell 1.
func RegionCell(region string) Cell { return Cell{Region: region, Index: 1} }

// Name returns the cell name, e.g. gru-1.
func (c Cell) Name() (string, error) {
	return valid(fmt.Sprintf("%s-%d", strings.ToLower(c.Region), c.Index))
}

// Image returns the name of the cell's qualified ARM64 host image, e.g.
// gru-1-arm64. A new image import reuses the name; the source revision and
// digest belong in its signed receipt.
func (c Cell) Image() (string, error) {
	name, err := c.Name()
	if err != nil {
		return "", err
	}
	return name + "-arm64", nil
}

// Node returns the name of the region's n-th node, e.g. ts-gru-1.
func (c Cell) Node(n int) (string, error) {
	return valid(fmt.Sprintf("ts-%s-%d", strings.ToLower(c.Region), n))
}

// Server returns the name of the cell's n-th server of role, e.g. gru-1-ctl-1.
func (c Cell) Server(role string, n int) (string, error) {
	return valid(fmt.Sprintf("%s-%d-%s-%d", strings.ToLower(c.Region), c.Index, role, n))
}

// PoolServer returns the name of the n-th host of a node pool, e.g.
// gru-1-pool-app-3. A pool name is 2 to 12 lower-case letters and digits,
// starting with a letter.
func (c Cell) PoolServer(pool string, n int) (string, error) {
	return valid(fmt.Sprintf("%s-%d-pool-%s-%d", strings.ToLower(c.Region), c.Index, pool, n))
}

// ControllerSlot returns the server name of a signed controller slot:
// controller-a, -b and -c are the region's nodes 1, 2 and 3 (ts-sfo-1). GRU
// keeps ctl-1, -2 and -3 (gru-1-ctl-1) until its servers are renamed: a
// controller refuses a NATS store of another server name.
func (c Cell) ControllerSlot(slot string) (string, error) {
	if strings.ToUpper(c.Region) == catalog.GRU {
		return c.slot(slot, "controller-", Controller)
	}
	letter, ok := strings.CutPrefix(slot, "controller-")
	if !ok || len(letter) != 1 || letter[0] < 'a' || letter[0] > 'z' {
		return "", fmt.Errorf("%w: controller-slot %q", ErrName, slot)
	}
	return c.Node(int(letter[0]-'a') + 1)
}

// MemberSlot returns the server name of a regional plan's database host
// slot: member-a and -b are db-1 and -2.
func (c Cell) MemberSlot(slot string) (string, error) { return c.slot(slot, "member-", Member) }

func (c Cell) slot(slot, prefix, role string) (string, error) {
	letter, ok := strings.CutPrefix(slot, prefix)
	if !ok || len(letter) != 1 || letter[0] < 'a' || letter[0] > 'z' {
		return "", fmt.Errorf("%w: %sslot %q", ErrName, prefix, slot)
	}
	return c.Server(role, int(letter[0]-'a')+1)
}

// API returns the name of the cell's public API load balancer, e.g.

func Validate(name string) error {
	match := nodeScheme.FindStringSubmatch(name)
	if match == nil {
		match = scheme.FindStringSubmatch(name)
	}
	if match == nil || !catalog.IsCell(strings.ToUpper(match[1])) {
		return fmt.Errorf("%w: %q", ErrName, name)
	}
	return nil
}

func valid(name string) (string, error) {
	if err := Validate(name); err != nil {
		return "", err
	}
	return name, nil
}

func Render(value any) (jsontext.Value, error) {
	wire, err := json.Marshal(value, json.FormatNilSliceAsNull(true))
	if err != nil {
		return nil, fmt.Errorf("encode OCI response: %w", err)
	}
	return kebab(jsontext.Value(wire), false)
}

// userKeyed are SDK members whose object keys are user data, not schema.
var userKeyed = map[string]bool{
	"freeformTags": true, "definedTags": true, "systemTags": true, "metadata": true, "extendedMetadata": true,
	"securityAttributes": true, "schemaData": true, "opcMeta": true, "lockedAttributes": true,
}

// nameKeyed are SDK members keyed by user-defined resource names (an NLB's
// backend sets and listeners, a load balancer's named sets) whose values are
// still schema objects: only the immediate keys are preserved, so a listener's
// default-backend-set-name keeps resolving to its backend set.
var nameKeyed = map[string]bool{
	"backendSets": true, "listeners": true, "certificates": true, "hostnames": true,
	"pathRouteSets": true, "ruleSets": true, "routingPolicies": true, "sslCipherSuites": true,
}

func kebab(value jsontext.Value, preserveKeys bool) (jsontext.Value, error) {
	switch value.Kind() {
	case '{':
		var typed map[string]jsontext.Value
		if err := json.Unmarshal(value, &typed); err != nil {
			return nil, err
		}
		result := make(map[string]jsontext.Value, len(typed))
		for key, member := range typed {
			name := key
			if !preserveKeys {
				name = Kebab(key)
			}
			if member.Kind() == '{' && !preserveKeys && nameKeyed[key] {
				var named map[string]jsontext.Value
				if err := json.Unmarshal(member, &named); err != nil {
					return nil, err
				}
				entries := make(map[string]jsontext.Value, len(named))
				for entryName, entry := range named {
					converted, err := kebab(entry, false)
					if err != nil {
						return nil, err
					}
					entries[entryName] = converted
				}
				encoded, err := json.Marshal(entries, json.Deterministic(true))
				if err != nil {
					return nil, err
				}
				result[name] = encoded
				continue
			}
			// The members of a user-keyed map are user data at any depth
			// (defined tags nest one level), so preserve keys below it.
			converted, err := kebab(member, preserveKeys || userKeyed[key])
			if err != nil {
				return nil, err
			}
			result[name] = converted
		}
		wire, err := json.Marshal(result, json.Deterministic(true))
		return jsontext.Value(wire), err
	case '[':
		var typed []jsontext.Value
		if err := json.Unmarshal(value, &typed); err != nil {
			return nil, err
		}
		result := make([]jsontext.Value, len(typed))
		for index, member := range typed {
			converted, err := kebab(member, preserveKeys)
			if err != nil {
				return nil, err
			}
			result[index] = converted
		}
		wire, err := json.Marshal(result)
		return jsontext.Value(wire), err
	default:
		return value, nil
	}
}

