func (a *Attempt) PhaseServices() {
	services, err := a.cellServices()
	if a.fail(err); a.err != nil || len(services) == 0 {
		return
	}
	// A role names files the phase deletes as root.
	for _, v := range services {
		service := object(v)
		if !serviceRole.MatchString(str(service, "role")) || str(service, "profile") == "" {
			a.fail(fmt.Errorf("attempt config services need a valid role and a profile"))
			return
		}
	}
	dir := a.Path("services")
	a.mkdir(dir)
	// Every run issues a fresh delegation, so a resumed attempt never signs
	// with an expired one.
	delegation := filepath.Join(dir, "spec-delegation.signed.json")
	if err := os.Remove(delegation); !errors.Is(err, os.ErrNotExist) {
		a.fail(err)
	}
	issued := a.Now().UTC().Truncate(time.Second).Add(-time.Minute)
	a.release("sign-spec-delegation", "--subject-public-key", a.trust("release_leaf_public"), "--root-key", a.trust("root_public"), "--signing-key", a.trust("root_private"), "--deployment-id", a.Deployment, "--cell", a.Cell().Name(), "--environment", "canary", "--issued-at", issued.Format(time.RFC3339), "--expires-at", issued.Add(7*24*time.Hour).Format(time.RFC3339), "--out", delegation)
	cli, config := a.Path("release", OperatorCLI), filepath.Join(a.OperatorDirectory(), "operator.json")
	apply := func(candidate, signed string, root bool) {
		if root {
			a.release("sign-spec", "--candidate", candidate, "--root", "--root-key", a.trust("root_public"), "--signing-key", a.trust("root_private"), "--out", signed)
		} else {
			a.release("sign-spec", "--candidate", candidate, "--delegation", delegation, "--root-key", a.trust("root_public"), "--signing-key", a.trust("release_leaf_private"), "--out", signed)
		}
		a.sudo(false, cli, "service", "apply", "--config", config, "--file", signed)
	}
	for _, v := range services {
		service := object(v)
		role, profile, spec := str(service, "role"), str(service, "profile"), str(service, "spec")
		// Every run plans from the cell's current spec, so a spec another
		// change made stale is never reapplied.
		candidate, signed := filepath.Join(dir, role+".candidate.json"), filepath.Join(dir, role+".signed.json")
		a.sudo(false, "rm", "-f", "--", candidate, signed)
		args := []string{cli, "service", "add", "--config", config, "--role", role, "--profile", profile, "--out", candidate}
		if spec != "" {
			args = append(args, "--spec", spec)
		}
		plan := a.sudo(true, args...)
		if a.err != nil {
			return
		}
		if !exists(candidate) {
			continue
		}
		// The leader's plan names what only a root may sign, such as a
		// role's Vault secrets; the attempt holds the root key.
		var planned struct {
			RootRequired []string `json:"root_required"`
		}
		if a.fail(json.Unmarshal([]byte(plan), &planned)); a.err != nil {
			return
		}
		apply(candidate, signed, len(planned.RootRequired) != 0)
	}
	a.grantHosts(services, apply)
}

// cellServices lists the services the services phase applies: TerraBase and
// ts-auth from their attempt settings, or derived from the plan when the
// config names them neither there nor in services, then the configured
// services. A role set both ways is refused rather than one source silently
// winning.
func (a *Attempt) cellServices() ([]any, error) {
	if (str(a.Config, "ts_auth_profile") == "") != (str(a.Config, "ts_auth_service") == "") {
		return nil, errors.New("attempt config needs ts_auth_profile and ts_auth_service together")
	}
	configured := rows(a.Config["services"])
	named := func(role string) string {
		for _, v := range configured {
			if str(object(v), "role") == role {
				return str(object(v), "profile")
			}
		}
		return ""
	}
	roles := []string{terrabase.Role, tsauth.Role}
	own := map[string][2]string{
		terrabase.Role: {str(a.Config, "terrabase_profile")},
		tsauth.Role:    {str(a.Config, "ts_auth_profile"), str(a.Config, "ts_auth_service")},
	}
	for _, role := range roles {
		if own[role][0] != "" && named(role) != "" {
			return nil, fmt.Errorf("attempt config names %s in services and in its own settings; keep one", role)
		}
	}
	terraBase := cmp.Or(own[terrabase.Role][0], named(terrabase.Role))
	if tsAuth := own[tsauth.Role][0] == "" && named(tsauth.Role) == ""; terraBase == "" || tsAuth {
		derived, err := a.deriveServices(terraBase, tsAuth)
		if err != nil {
			return nil, err
		}
		maps.Copy(own, derived)
	}
	var services []any
	for _, role := range roles {
		if own[role][0] == "" {
			continue
		}
		service := Object{"role": role, "profile": own[role][0]}
		if own[role][1] != "" {
			service["spec"] = own[role][1]
		}
		services = append(services, service)
	}
	return append(services, configured...), nil
}

func (a *Attempt) profileEnv(path string) map[string]string {
	env := map[string]string{}
	for key, value := range object(a.read(path)["env"]) {
		env[key], _ = value.(string)
	}
	return env
}

// grantHosts plans a host grant for every controller node of the plan with
// the colocated roles the cell delivers in services: ts-auth, and
// TerraBase where the TerraBase profile lists the node as a member. A grant
// gives a host credentials, so a root signs it. A grant the spec already
// holds plans nothing, so a rerun changes nothing.
func (a *Attempt) grantHosts(services []any, apply func(candidate, signed string, root bool)) {
	roles := map[string]string{}
	for _, v := range services {
		roles[str(object(v), "role")] = str(object(v), "profile")
	}
	var members terrabase.Profile
	if path, ok := roles[terrabase.Role]; ok {
		var err error
		members, err = terrabase.ParseProfile(a.profileEnv(path))
		a.fail(err)
	}
	plan := a.read(a.Plan())
	cell := a.Cell()
	if a.err != nil {
		return
	}
	hosts := hostMap(plan)
	cli, config := a.Path("release", OperatorCLI), filepath.Join(a.OperatorDirectory(), "operator.json")
	for _, slot := range Slots {
		name, err := naming.RegionCell(cell.Cell).ControllerSlot(slot)
		a.fail(err)
		ip := str(hosts[slot], "private_ip")
		var granted []string
		if _, ok := roles[tsauth.Role]; ok {
			granted = append(granted, tsauth.Role)
		}
		if _, ok := members.Member(name, ip); ok {
			granted = append(granted, terrabase.Role)
		}
		if a.err != nil || len(granted) == 0 {
			continue
		}
		slices.Sort(granted)
		candidate, signed := a.Path("services", "grant-"+name+".candidate.json"), a.Path("services", "grant-"+name+".signed.json")
		a.sudo(false, "rm", "-f", "--", candidate, signed)
		a.sudo(true, cli, "service", "grant-host", "--config", config, "--node", name, "--private-ip", ip,
			"--roles", strings.Join(granted, ","), "--environment", "canary", "--controller", slot, "--out", candidate)
		if a.err == nil && exists(candidate) {
			apply(candidate, signed, true)
		}
	}
}

// deriveServices writes the profiles of the cell's roles the attempt config
// does not name, from the attempt's bound plan, and returns their paths.
func (a *Attempt) deriveServices(terraBaseConfigured string, tsAuth bool) (map[string][2]string, error) {
	plan := a.read(a.Plan())
	cell := a.Cell()
	if a.err != nil {
		return nil, a.err
	}
	paths := map[string][2]string{}
	terraBase := terraBaseConfigured
	if terraBase == "" {
		profile, err := deriveTerraBase(cell, plan)
		if err != nil {
			return nil, err
		}
		terraBase = a.derivedProfile(terrabase.Role)
		a.writeJSON(terraBase, profile)
		paths[terrabase.Role] = [2]string{terraBase}
	}
	if tsAuth {
		env := a.profileEnv(terraBase)
		if a.err != nil {
			return nil, a.err
		}
		profile, spec, err := a.deriveTSAuth(cell, plan, env)
		if err != nil {
			return nil, err
		}
		path, specPath := a.derivedProfile(tsauth.Role), a.Path("services", tsauth.Role+".service.json")
		a.writeJSON(path, profile)
		a.writeJSON(specPath, spec)
		paths[tsauth.Role] = [2]string{path, specPath}
	}
	return paths, a.err
}

func ParseProfile(env map[string]string) (Profile, error) {
	for _, key := range hostOwned {
		if _, set := env[key]; set {
			return Profile{}, fmt.Errorf("terrabase profile must not set %s", key)
		}
	}
	profile := Profile{AdminPort: DefaultAdminPort}
	var err error
	if raw, set := env[EnvAdminPort]; set {
		if profile.AdminPort, err = parsePort(raw); err != nil {
			return Profile{}, fmt.Errorf("%s: %w", EnvAdminPort, err)
		}
	}
	if profile.PeerPort, err = parsePort(env[EnvPeerPort]); err != nil {
		return Profile{}, fmt.Errorf("%s: %w", EnvPeerPort, err)
	}
	if raw, set := env[EnvClientPort]; set {
		if profile.ClientPort, err = parsePort(raw); err != nil {
			return Profile{}, fmt.Errorf("%s: %w", EnvClientPort, err)
		}
	}
	if profile.Peers, err = ParsePeers(env[EnvPeers]); err != nil {
		return Profile{}, err
	}
	for _, peer := range profile.Peers {
		if int(peer.Address.Port()) != profile.PeerPort {
			return Profile{}, fmt.Errorf("%s: peer %s does not use %s", EnvPeers, peer.Name, EnvPeerPort)
		}
	}
	if profile.AdminPort == profile.PeerPort || profile.ClientPort == profile.AdminPort || profile.ClientPort == profile.PeerPort {
		return Profile{}, errors.New("terrabase admin, peer and client ports must differ")
	}
	return profile, nil
}

// Peer returns the member named node.
func (p Profile) Peer(node string) (Peer, bool) {
	index := slices.IndexFunc(p.Peers, func(peer Peer) bool { return peer.Name == node })
	if index < 0 {
		return Peer{}, false
	}
	return p.Peers[index], true
}

// Member returns the member a host runs: the one named after its node, or
// else the one at the host's private address, which outlives a rename of
// the node (TS-609 keeps member names such as gru-1-ctl-1). Members share
// one peer port, so an address names at most one.
func (p Profile) Member(node, address string) (Peer, bool) {
	if peer, ok := p.Peer(node); ok {
		return peer, true
	}
	index := slices.IndexFunc(p.Peers, func(peer Peer) bool { return peer.Address.Addr().String() == address })
	if index < 0 {
		return Peer{}, false
	}
	return p.Peers[index], true
}

// ParsePeers parses name=ip:port entries with unique names and addresses.
func ParsePeers(raw string) ([]Peer, error) {
	if raw == "" {
		return nil, fmt.Errorf("%s is required", EnvPeers)
	}
	entries := strings.Split(raw, ",")
	if len(entries) > 64 {
		return nil, fmt.Errorf("%s lists more than 64 members", EnvPeers)
	}
	peers := make([]Peer, 0, len(entries))
	for _, entry := range entries {
		name, address, found := strings.Cut(entry, "=")
		addrPort, err := netip.ParseAddrPort(address)
		if !found || !nameRE.MatchString(name) || err != nil || addrPort.String() != address ||
			addrPort.Port() == 0 || !addrPort.Addr().IsValid() || addrPort.Addr().IsUnspecified() {
			return nil, fmt.Errorf("%s entry %q is not name=ip:port", EnvPeers, entry)
		}
		if addrPort.Addr().Zone() != "" || addrPort.Addr().IsLinkLocalUnicast() || addrPort.Addr().IsLinkLocalMulticast() {
			return nil, fmt.Errorf("%s entry %q: zone identifiers and link-local addresses are not supported", EnvPeers, entry)
		}
		if slices.ContainsFunc(peers, func(p Peer) bool { return p.Name == name || p.Address == addrPort }) {
			return nil, fmt.Errorf("%s repeats member %q or its address", EnvPeers, name)
		}
		peers = append(peers, Peer{Name: name, Address: addrPort})
	}
	return peers, nil
}

func parsePort(raw string) (int, error) {
	port, err := strconv.Atoi(raw)
	if err != nil || port < 1 || port > 65535 || strconv.Itoa(port) != raw {
		return 0, errors.New("must be a port between 1 and 65535")
	}

func OperatorDirectory(cell string) string {
	if cell == "gru" {
		return "/var/lib/terrascale-operator"
	}
	return "/var/lib/terrascale-operator-" + cell
}

sign.text:
func (a *Attempt) pair(path, flag string) []string {
	return []string{flag, path, flag + "-sha256", a.sha(path)}
}
func join(parts ...[]string) []string {
	var result []string
	for _, part := range parts {
		result = append(result, part...)
	}
	return result
}
func (a *Attempt) validity() (string, string) {
	path := a.Path("validity.json")
	if !exists(path) {
		issued := a.Now().UTC().Truncate(time.Second).Add(-time.Minute)
		a.writeJSON(path, Object{"issued_at": issued.Format(time.RFC3339), "expires_at": issued.Add(time.Duration(num(a.Config["validity_days"])*24) * time.Hour).Format(time.RFC3339)})
	}
	o := a.read(path)
	return str(o, "issued_at"), str(o, "expires_at")
}

func hostMap(plan Object) map[string]Object {
	m := map[string]Object{}
	for _, v := range rows(plan["hosts"]) {
		h := object(v)
		m[str(h, "slot")] = h
	}
	return m
}
func (a *Attempt) validFor() string { return text(num(a.Config["validity_days"])*24) + "h" }

func (a *Attempt) Kernel() string              { return a.Path("image", "guest-kernel") }
func (a *Attempt) ImageReceipt() string        { return a.Path("image", "image-receipt.signed.json") }
func (a *Attempt) ImageID() string             { return str(a.read(a.Path("image", "import.json")), "image_id") }
func (a *Attempt) Manifest(slot string) string { return a.Path("signed", slot+".manifest.signed.json") }

func (a *Attempt) PhaseSign() {
	signed := a.Path("signed")
	a.mkdir(signed)
	plan := a.read(a.Plan())
	hosts := hostMap(plan)
	ids := object(plan["resource_ids"])
	anchor := a.Path("anchor.signed.json")
	anchorPayload := object(a.read(anchor)["payload"])
	references := rows(a.read(a.Path("controller-vault-references.json"))["references"])
	cell := a.Cell()
	// The fleet launches managed hosts into the database hosts' fault
	// domains, or the controllers' in a cell whose nodes are its controllers.
	var fleet []Object
	for _, v := range rows(plan["hosts"]) {
		if strings.HasPrefix(str(object(v), "slot"), "member-") {
			fleet = append(fleet, object(v))
		}
	}
	if len(fleet) == 0 {
		for _, slot := range Slots {
			fleet = append(fleet, hosts[slot])
		}
	}
	var faultDomains []any
	maxData := 50.0
	for _, h := range fleet {
		if !slices.Contains(faultDomains, h["fault_domain"]) {
			faultDomains = append(faultDomains, h["fault_domain"])
		}
		maxData = max(maxData, num(h["data_gb"]))
	}
	region := a.Path("signed", "oci-region.json")
	a.writeJSON(region, Object{"region": cell.Cell, "generation": 1, "endpoint": "https://iaas." + cell.OCIRegion + ".oraclecloud.com", "compartment_id": ids["workload_compartment"], "image_compartment_id": ids["control_compartment"], "availability_domain": plan["availability_domain"], "fault_domains": faultDomains, "subnet_id": ids["subnet"], "network_security_group_ids": []any{ids["workload_network_security_group"]}, "image_id": a.ImageID(), "shape": "VM.Standard.A1.Flex", "boot_volume_gb": 50, "boot_volume_vpus_per_gb": plan["volume_vpus_per_gb"], "data_volume_vpus_per_gb": plan["volume_vpus_per_gb"], "max_data_volume_gb": maxData, "owner": a.Prefix})
	sidecars := join(a.pair(str(a.Config, "region_intent"), "--oci-region-intent"), a.pair(region, "--oci-region-config"), a.pair(str(a.Config, "placement_config"), "--placement-config"))
	receipt, delegation := a.ImageReceipt(), a.Path("image", "image-delegation.signed.json")
	// Embed the signed envelope's bytes: its payload is raw JSON, and
	// re-encoding a decoded map sorts the payload's keys and voids the
	// signature.
	peerWire, e := os.ReadFile(a.Path("peer-receipt-delegation.signed.json"))
	a.fail(e)
	peer := jsontext.Value(bytes.TrimSpace(peerWire))
	domain := a.read(str(a.Config, "managed_material_domain"))
	domain["nativeVerifierSha256"] = object(a.Config["image"])["native_verifier_sha256"]
	var profiles []any
	for _, slot := range Slots {
		nsgs := []string{str(ids, "network_security_group")}
		profiles = append(profiles, Object{"slot": slot, "compartmentOcid": ids["control_compartment"], "availabilityDomain": plan["availability_domain"], "faultDomain": hosts[slot]["fault_domain"], "subnetOcid": ids["subnet"], "networkSecurityGroupOcids": nsgs, "shape": hosts[slot]["shape"]})
	}
	// The signed controller configs hold the cell's identity only; the
	// services phase applies TerraBase's and ts-auth's profiles as the first
	// cell spec. Configs an earlier attempt rendered with them keep them.
	if (str(a.Config, "ts_auth_profile") == "") != (str(a.Config, "ts_auth_service") == "") {
		a.fail(errors.New("attempt config needs ts_auth_profile and ts_auth_service together"))
		return
	}
	// A retained config's workload stays generation 0 until a cell spec
	// replaces it, so the attempt must still apply the role it carries.
	for _, slot := range Slots {
		config := a.Path("signed", slot+".config.json")
		if !exists(config) {
			continue
		}
		workloads := object(object(a.read(config)["controller"])["workloads"])
		for role, setting := range map[string]string{terrabase.Role: "terrabase_profile", tsauth.Role: "ts_auth_profile"} {
			if _, rendered := workloads[role]; rendered && str(a.Config, setting) == "" {
				a.fail(fmt.Errorf("%s was rendered with %s; keep %s so the cell spec carries it", config, role, setting))
				return
			}
		}
	}
	for _, slot := range Slots {
		manifest := a.Manifest(slot)
		if exists(manifest) {
			continue
		}
		var secrets []any
		for _, v := range references {
			ref := object(object(v)["reference"])
			if ref["purpose"] == "regional-shared" || ref["purpose"] == "host-issuer" || ref["slot"] == slot {
				secrets = append(secrets, ref)
			}
		}
		candidate, config := a.Path("signed", slot+".candidate.json"), a.Path("signed", slot+".config.json")
		a.writeJSON(candidate, Object{"schemaVersion": bootstrap.ManifestSchemaVersion, "deploymentId": a.Deployment, "environment": "canary", "clusterId": a.Deployment, "cell": cell.Cell, "ociRegion": cell.OCIRegion, "intentGeneration": anchorPayload["initialRegionIntentGeneration"], "intentSha256": anchorPayload["initialRegionIntentSha256"], "controllerRole": "controller", "slot": slot, "seedSlot": "controller-a", "controllerSlots": Slots, "profiles": profiles, "imageOcid": a.ImageID(), "imageArchitecture": "linux-arm64", "releaseReceiptSha256": a.sha(receipt), "peerReceiptDelegation": peer, "storageDomain": anchorPayload["storageDomain"], "managedMaterial": domain, "secrets": secrets})
		if !exists(config) {
			args := join([]string{"render-controller-config"}, a.pair(candidate, "--candidate"), a.pair(a.Path("controller-material.json"), "--material-record"), a.pair(str(a.Config, "operator_grant"), "--operator-grant"), sidecars)
			a.RunBootstrap(append(args, "--out", config)...)
		}
		a.RunBootstrap(join([]string{"sign-manifest", "--candidate", candidate}, a.pair(config, "--controller-config"), sidecars, []string{"--anchor", anchor, "--image-receipt", receipt, "--release-delegation", delegation, "--root-key", a.trust("root_public"), "--signing-key", a.trust("root_private"), "--out", manifest, "--valid-for", a.validFor()})...)
		verified := a.bootstrapCapture("verify-manifest", "--anchor", anchor, "--manifest", manifest, "--identity", a.Path("identity.json"), "--slot", slot, "--image-ocid", a.ImageID(), "--root-key", a.trust("root_public"))
		a.WriteNew(a.Path("signed", slot+".verify.json"), []byte(verified))
	}
	founder, selection := a.Path("signed", "founder-plan.signed.json"), a.Path("signed", "founder-selection.signed.json")
	var manifests []string
	for _, slot := range Slots {
		manifests = append(manifests, "--manifest", a.Manifest(slot))
	}
	identity := a.Path("identity.json")
	if !exists(founder) {
		vault := Object{}
		for _, v := range references {
			r := object(object(v)["reference"])
			vault[str(r, "targetFile")] = r["sha256"]
		}
		var peers []any
		budget := Object{"wholeOcpus": 0.0, "memoryInGb": 0.0, "bootVolumeGb": 0.0}
		for _, slot := range []string{"controller-b", "controller-c"} {
			profile := object(a.read(a.Path("signed", slot+".verify.json"))["profile"])
			h := hosts[slot]
			var routes []any
			for _, name := range Slots {
				if name != slot {
					routes = append(routes, Object{"slot": name, "privateIp": hosts[name]["private_ip"], "port": 6222})
				}
			}
			peers = append(peers, Object{"slot": slot, "manifestSha256": a.sha(a.Manifest(slot)), "imageOcid": a.ImageID(), "image_compartment_ocid": ids["control_compartment"], "compartmentOcid": profile["compartmentOcid"], "availabilityDomain": profile["availabilityDomain"], "faultDomain": profile["faultDomain"], "subnetOcid": profile["subnetOcid"], "networkSecurityGroupOcids": profile["networkSecurityGroupOcids"], "shape": h["shape"], "wholeOcpus": h["ocpus"], "memoryInGb": h["memory_gb"], "bootVolumeGb": h["boot_gb"], "bootVolumeTier": "balanced", "privateIp": h["private_ip"], "routeEndpoints": routes, "clientEndpoints": []any{Object{"slot": slot, "privateIp": h["private_ip"], "port": 4222}}, "tlsMaterial": Object{"clientCaSha256": vault["ca.pem"], "clientCertificateSha256": vault[slot+"-tls-cert.pem"], "clientPrivateKeySha256": vault[slot+"-tls-key.pem"], "routeCaSha256": vault["ca.pem"], "routeCertificateSha256": vault[slot+"-tls-cert.pem"], "routePrivateKeySha256": vault[slot+"-tls-key.pem"]}})
			budget["wholeOcpus"] = num(budget["wholeOcpus"]) + num(h["ocpus"])
			budget["memoryInGb"] = num(budget["memoryInGb"]) + num(h["memory_gb"])
			budget["bootVolumeGb"] = num(budget["bootVolumeGb"]) + num(h["boot_gb"])
		}
		deadline := a.Now().UTC().Add(22 * time.Hour).Truncate(time.Minute)
		candidate := a.Path("signed", "founder-plan.candidate.json")
		if exists(candidate) {
			// Resume the already rendered launch window rather than changing a
			// record that may have been retained before signing was interrupted.
			retained := a.read(candidate)
			var err error
			deadline, err = time.Parse(time.RFC3339, str(retained, "launchDeadline"))
			a.fail(err)
		}
		// sign-founder-plan requires FounderPlan's canonical field order.
		a.writeJSON(candidate, typed(a, Object{"schemaVersion": 1, "deploymentId": a.Deployment, "cell": cell.Cell, "environment": "canary", "seedSlot": "controller-a", "anchorSha256": a.sha(anchor), "controllerSlots": Slots, "seedManifestSha256": a.sha(a.Manifest("controller-a")), "seedPrivateIp": hosts["controller-a"]["private_ip"], "peers": peers, "budget": budget, "launchDeadline": deadline.Format(time.RFC3339)}, &bootstrap.FounderPlan{}))
		a.RunBootstrap(join([]string{"sign-founder-plan", "--candidate", candidate, "--identity", identity, "--anchor", anchor}, manifests, []string{"--root-key", a.trust("root_public"), "--signing-key", a.trust("root_private"), "--out", founder, "--valid-for", "24h"})...)
	}
	if !exists(selection) {
		candidate := a.Path("signed", "founder-selection.candidate.json")
		var ms []any
		for _, slot := range Slots {
			ms = append(ms, Object{"slot": slot, "sha256": a.sha(a.Manifest(slot))})
		}
		// The selector signers require FounderSelection's canonical field order.
		a.writeJSON(candidate, typed(a, Object{"schemaVersion": 1, "deploymentId": a.Deployment, "cell": cell.Cell, "environment": "canary", "generation": 1, "planSha256": a.sha(founder), "anchorSha256": a.sha(anchor), "manifests": ms}, &bootstrapstart.FounderSelection{}))
		a.RunBootstrap(join([]string{"sign-initial-founder-selection", "--candidate", candidate, "--identity", identity, "--anchor", anchor, "--plan", founder}, manifests, []string{"--root-key", a.trust("root_public"), "--signing-key", a.trust("root_private"), "--out", selection, "--valid-for", "24h"})...)
	}
	a.RunBootstrap(join([]string{"publish-initial-founder-selection", "--selection", selection, "--identity", identity, "--anchor", anchor, "--plan", founder}, manifests, []string{"--root-key", a.trust("root_public"), "--oci-config", a.ociConfig(), "--oci-profile", "DEFAULT"})...)

