const terrabaseCommit = "641274f7482bcf0ce2ae556af8be162d49e445be"

// taggedCommit is the commit `git rev-parse` resolves a version tag to.
var taggedCommit = terrabaseCommit

// terrabaseAttempt has the arm64 release fixture already downloaded.
func terrabaseAttempt(t *testing.T, commit string) (*Attempt, *[][]string) {
	t.Helper()
	a := smallAttempt(t)
	a.Config["terrabase"] = Object{"tag": "ci-" + terrabaseCommit + "-run-1", "commit": commit, "environment": "canary"}
	a.Config["terrabase_profile"] = "/etc/terrabase/profile.json"
	for _, asset := range []string{"terrabase-linux-arm64", "terrabase-linux-arm64.sha256"} {
		b, err := os.ReadFile(filepath.Join("..", "terrabase", "testdata", asset))
		if err == nil {
			err = a.WriteNew(a.Path("terrabase", "ci-"+terrabaseCommit+"-run-1", asset), b)
		}
		if err != nil {
			t.Fatal(err)
		}
	}
	var commands [][]string
	a.Runner = func(_ context.Context, c Command) (string, error) {
		commands = append(commands, c.Args)
		if slices.Contains(c.Args, "rev-parse") {
			return taggedCommit + "\n", nil
		}
		if c.Args[0] == "gh" {
			b, err := os.ReadFile(filepath.Join("..", "terrabase", "testdata", flagValue(c.Args, "--pattern")))
			if err != nil {
				return "", err
			}
			return "", os.WriteFile(flagValue(c.Args, "--output"), b, 0600)
		}
		return "", nil
	}
	return a, &commands
}

func (a *Attempt) PhaseTerraBase() {
	release := object(a.Config["terrabase"])
	tag, commit, environment, profile := str(release, "tag"), str(release, "commit"), str(release, "environment"), a.terraBaseProfile()
	if tag == "" || filepath.Base(tag) != tag || strings.HasPrefix(tag, ".") || len(commit) != 40 ||
		strings.Trim(commit, "0123456789abcdef") != "" || environment == "" || profile == "" {
		a.fail(fmt.Errorf("attempt config needs terrabase tag, a 40-hex commit and environment, and terrabase_profile or a services run that derives it"))
		return
	}
	// The rollout records commit as the binary's source, so it must be the
	// commit the release tag names: a CI prerelease tag carries it, and a
	// version tag is resolved in the clone below.
	tagged, ciTag := ciReleaseCommit(tag)
	if ciTag && tagged != commit {
		a.fail(fmt.Errorf("terrabase release %s is commit %s, not the configured %s", tag, tagged, commit))
		return
	}
	// Assets are kept per tag: a new release never reuses the previous
	// release's downloads under its own commit.
	dir := a.Path("terrabase", tag)
	a.mkdir(dir)
	binary := filepath.Join(dir, "terrabase-linux-arm64")
	checksum := binary + ".sha256"
	for _, asset := range []string{binary, checksum} {
		if !exists(asset) {
			a.run("gh", "release", "download", tag, "--repo", "TerraScale/terrabase", "--pattern", filepath.Base(asset), "--output", asset)
		}
	}
	if a.err != nil {
		return
	}
	_, e := terrabase.VerifyRelease(binary, checksum)
	a.fail(e)
	source := a.Path("terrabase", "source")
	if !exists(source) {
		a.run("git", "clone", "--quiet", terrabase.Repository, source)
	} else {
		a.run("git", "-C", source, "fetch", "--quiet", "--tags", "origin")
	}
	a.run("git", "-C", source, "cat-file", "-e", commit+"^{commit}")
	if !ciTag {
		if resolved := strings.TrimSpace(a.capture("git", "-C", source, "rev-parse", "--verify", "--end-of-options", tag+"^{commit}")); a.err == nil && resolved != commit {
			a.fail(fmt.Errorf("terrabase release %s is commit %s, not the configured %s", tag, resolved, commit))
			return
		}
	}
	a.sudo(false, a.Path("release", OperatorCLI), "operator", "terrabase-release", "--config", filepath.Join(a.OperatorDirectory(), "operator.json"), "--binary", binary, "--sha256", checksum, "--source-checkout", source, "--commit", commit, "--environment", environment, "--profile", profile, "--wait", "10m")
}

// ciReleaseCommit returns the commit of a TerraBase CI prerelease tag,
// ci-<commit>-run-<run id>.
func ciReleaseCommit(tag string) (string, bool) {
	rest, ok := strings.CutPrefix(tag, "ci-")
	commit, run, found := strings.Cut(rest, "-run-")
	if !ok || !found || len(commit) != 40 || strings.Trim(commit, "0123456789abcdef") != "" ||
		run == "" || strings.Trim(run, "0123456789") != "" {
		return "", false
	}
	return commit, true
}

func (a *Attempt) derivedProfile(role string) string { return a.Path("services", role+".profile.json") }

// terraBaseProfile is the TerraBase profile the cell runs: terrabase_profile,
// or the one the services phase derived.
func (a *Attempt) terraBaseProfile() string {
	if path := str(a.Config, "terrabase_profile"); path != "" {
		return path
	}
	if path := a.derivedProfile(terrabase.Role); exists(path) {
		return path
	}
	return ""
}

// Repository is the source of every TerraBase release.
const Repository = "https://github.com/TerraScale/terrabase"

// Release assets are terrabase-linux-<arch> and terrabase-linux-<arch>.sha256,
// attached to the prerelease ci-<commit>-run-<run> of each main push and to
// the release v<version> of each version tag.
var assetRE = regexp.MustCompile(`^terrabase-linux-(?:amd64|arm64)$`)

// maxBinaryBytes matches the controller's artifact admission limit.
const maxBinaryBytes = 512 << 20

// VerifyRelease checks a downloaded release executable against its
// published .sha256 asset and returns the digest to pin. The checksum file
// must hold exactly one sha256sum line naming the executable's asset.
func VerifyRelease(binaryPath, checksumPath string) (string, error) {
	return VerifyAsset(binaryPath, checksumPath, assetRE)
}

// VerifyAsset is VerifyRelease for any single-file release executable whose
// asset name matches asset, such as ts-auth-linux-arm64.
func VerifyAsset(binaryPath, checksumPath string, asset *regexp.Regexp) (string, error) {
	name := filepath.Base(binaryPath)
	if !asset.MatchString(name) {
		return "", fmt.Errorf("release executable %q is not one of %s", name, asset)
	}
	checksum, err := os.ReadFile(checksumPath)
	if err != nil {
		return "", err
	}
	fields := strings.Fields(string(checksum))
	if len(fields) != 2 || bytes.Count(checksum, []byte("\n")) > 1 || strings.TrimPrefix(fields[1], "*") != name ||
		len(fields[0]) != 64 || strings.ToLower(fields[0]) != fields[0] {
		return "", fmt.Errorf("%s is not one sha256sum line for %s", checksumPath, name)
	}
	if _, err := hex.DecodeString(fields[0]); err != nil {
		return "", fmt.Errorf("%s is not one sha256sum line for %s", checksumPath, name)
	}
	file, err := os.Open(binaryPath)
	if err != nil {
		return "", err
	}
	defer file.Close()
	hash := sha256.New()
	// The asset name is the architecture the hosts run: an executable built
	// for another machine would otherwise fail only once it reached them.
	var header elf.Header64
	if err := binary.Read(io.TeeReader(file, hash), binary.LittleEndian, &header); err != nil || string(header.Ident[:4]) != elf.ELFMAG {
		return "", fmt.Errorf("%s is not an ELF executable", binaryPath)
	}
	if elf.Class(header.Ident[elf.EI_CLASS]) != elf.ELFCLASS64 || elf.Data(header.Ident[elf.EI_DATA]) != elf.ELFDATA2LSB {
		return "", fmt.Errorf("%s is not a 64-bit little-endian ELF executable", binaryPath)
	}
	want := map[string]elf.Machine{"amd64": elf.EM_X86_64, "arm64": elf.EM_AARCH64}[name[strings.LastIndexByte(name, '-')+1:]]
	if got := elf.Machine(header.Machine); got != want {
		return "", fmt.Errorf("%s must be built for %v, found %v", name, want, got)
	}
	size, err := io.Copy(hash, io.LimitReader(file, maxBinaryBytes))
	if err != nil {
		return "", err
	}
	if size+int64(binary.Size(header)) > maxBinaryBytes {
		return "", errors.New("release executable exceeds the artifact admission limit")
	}
	if digest := hex.EncodeToString(hash.Sum(nil)); digest != fields[0] {
		return "", fmt.Errorf("%s has SHA-256 %s, its release checksum says %s", name, digest, fields[0])
	}
	return fields[0], nil
}

func OperatorDirectory(cell string) string {
	if cell == "gru" {
		return "/var/lib/terrascale-operator"
	}
	return "/var/lib/terrascale-operator-" + cell
}

