func (a *Attempt) validity() (string, string) {
	path := a.Path("validity.json")
	if !exists(path) {
		issued := a.Now().UTC().Truncate(time.Second).Add(-time.Minute)
		a.writeJSON(path, Object{"issued_at": issued.Format(time.RFC3339), "expires_at": issued.Add(time.Duration(num(a.Config["validity_days"])*24) * time.Hour).Format(time.RFC3339)})
	}
	o := a.read(path)
	return str(o, "issued_at"), str(o, "expires_at")
}

func (a *Attempt) Kernel() string              { return a.Path("image", "guest-kernel") }
func (a *Attempt) ImageReceipt() string        { return a.Path("image", "image-receipt.signed.json") }
func (a *Attempt) ImageID() string             { return str(a.read(a.Path("image", "import.json")), "image_id") }
func (a *Attempt) Manifest(slot string) string { return a.Path("signed", slot+".manifest.signed.json") }
func (a *Attempt) PhaseImage() {
	image := object(a.Config["image"])
	orch := object(a.Config["orchestrator"])
	revision := str(orch, "source_revision")
	release := a.Path("release")
	cell := a.Cell()
	// The base image's own record: GRU's unless the config names another.
	baseRegion := str(image, "base_image_region")
	if baseRegion == "" {
		baseRegion = catalog.GRU
	}
	qcow2 := a.Path("image", "terrascale-arm64.qcow2")
	if !exists(qcow2) {
		a.mkdir(filepath.Dir(qcow2))
		priority := object(image["priority"])
		args := []string{"bash", a.Path("source", "deploy/image/build-offline.sh"), "--base", str(image, "base_qcow2"), "--kernel-release", str(image, "kernel_release"), "--binary", filepath.Join(release, "terrascale-orchestrator-linux-arm64"), "--qualification", filepath.Join(release, "qualification.json"), "--source-revision", revision, "--native-verifier-binary", str(image, "native_verifier"), "--native-verifier-sha256", str(image, "native_verifier_sha256"), "--release-tool", a.ReleaseTool(), "--bootstrap-root", a.trust("root_public"), "--timesyncd-config", str(image, "timesyncd_config"), "--runtime-priority-profile-id", str(priority, "profile_id")}
		for _, p := range [][2]string{{"--runtime-priority-system-reserve-bytes", "system_reserve_bytes"}, {"--host-memory-min-bytes", "host_memory_min_bytes"}, {"--host-memory-low-bytes", "host_memory_low_bytes"}, {"--controller-memory-min-bytes", "controller_memory_min_bytes"}, {"--controller-memory-low-bytes", "controller_memory_low_bytes"}, {"--system-slice-memory-min-bytes", "system_slice_memory_min_bytes"}, {"--system-slice-memory-low-bytes", "system_slice_memory_low_bytes"}} {
			args = append(args, p[0], text(priority[p[1]]))
		}
		// NetBird is optional: a cell whose servers enroll as NetBird peers
		// bakes the pinned client and enrollment config into its image.
		if binary := str(image, "netbird_binary"); binary != "" {
			args = append(args, "--netbird-binary", binary, "--netbird-sha256", str(image, "netbird_sha256"), "--netbird-config", str(image, "netbird_config"))
		}
		args = append(args, "--out", qcow2, "--kernel-out", a.Kernel())
		a.execute(Command{Args: args, Dir: a.Path("source")})
	}
	digest := a.sha(qcow2)
	qualification := filepath.Join(release, "qualification.json")
	production := filepath.Join(release, "image-production")
	if !exists(filepath.Join(production, cell.Cell, "arm64", "production.json")) {
		tag := "ci-" + revision + "-run-" + text(orch["ci_run_id"])
		a.execute(Command{Args: []string{"bash", a.Path("source", "scripts/ci/fetch-image-production-evidence.sh"), tag, digest, cell.Cell, "arm64", production}, Dir: a.Path("source")})
	}
	// Recheck the exact final disk and retained proof before any import, including resumed attempts.
	a.release("verify-image-production", "--image-file", qcow2, "--qualification", qualification, "--root-key", a.trust("root_public"), "--cell", cell.Cell, "--environment", "canary", "--arch", "arm64", "--production-evidence-dir", production)
	if a.err != nil {
		return
	}
	imported := a.Path("image", "import.json")
	if !exists(imported) {
		plan := a.read(a.Plan())
		if a.err != nil {
			return
		}
		if len(revision) < 12 || len(digest) < 12 {
			a.fail(fmt.Errorf("image source or digest is malformed"))
			return
		}
		// The cell image name is static; the revision and digest are in the
		// signed image receipt.
		name, e := naming.RegionCell(cell.Cell).Image()
		if e != nil {
			a.fail(e)
			return
		}
		importer := a.imageImporter
		if importer == nil {
			importer = func(region string) (imageimport.Importer, error) {
				client, err := imageimport.NewSDKClient(region)
				return imageimport.Importer{Client: client}, err
			}
		}
		_, e = imageimport.ImportRegions(a.ctx, imageimport.Options{QCOW2: qcow2, SHA256: digest,
			Regions: []string{cell.OCIRegion}, Compartment: str(object(plan["resource_ids"]), "control_compartment"),
			Namespace: str(a.Config, "namespace"), Bucket: str(image, "bucket"), DisplayName: name, Out: imported}, a.Out, importer)
		if e != nil {
			a.fail(e)
			return
		}
	}
	imageID := str(a.read(imported), "image_id")
	issued, expires := a.validity()
	delegation := a.Path("image", "image-delegation.signed.json")
	if !exists(delegation) {
		a.release("sign-delegation", "--subject-public-key", a.trust("release_leaf_public"), "--root-key", a.trust("root_public"), "--signing-key", a.trust("root_private"), "--source-revision", revision, "--arch", "arm64", "--environment", "canary", "--image-cell", cell.Cell, "--image-ocid", imageID, "--previous-delegation", filepath.Join(release, "binary-delegation.signed.json"), "--issued-at", issued, "--expires-at", expires, "--out", delegation)
	}
	candidate, receipt := a.Path("image", "image-receipt.candidate.json"), a.ImageReceipt()
	common := []string{"--binary-receipt", filepath.Join(release, "binary-receipt.signed.json"), "--binary", filepath.Join(release, "terrascale-orchestrator-linux-arm64"), "--qualification", filepath.Join(release, "qualification.json"), "--delegation", delegation, "--root-key", a.trust("root_public"), "--environment", "canary", "--image-file", qcow2, "--base-image-file", str(image, "base_qcow2"), "--kernel-file", a.Kernel()}
	if !exists(candidate) {
		a.release(join([]string{"image-candidate"}, common, []string{"--base-image-ocid", str(image, "base_image_ocid"), "--base-image-region", baseRegion, "--kernel-release", str(image, "kernel_release"), "--image-ocid", imageID, "--region", cell.Cell, "--out", candidate})...)
	}
	if !exists(receipt) {
		a.release(join([]string{"sign-image", "--candidate", candidate}, common, []string{"--production-evidence-dir", production, "--signing-key", a.trust("release_leaf_private"), "--out", receipt})...)
	}
	a.release("verify-image", "--receipt", receipt, "--delegation", delegation, "--root-key", a.trust("root_public"), "--image-file", qcow2, "--base-image-file", str(image, "base_qcow2"), "--kernel-file", a.Kernel(), "--region", cell.Cell, "--environment", "canary")
}

func Start(t testing.TB, imageID string) *Server {
	t.Helper()
	s := &Server{imageID: imageID, created: time.Now().UTC().Truncate(time.Second), objects: map[string]object{},
		work: map[string]int{}, workIDs: map[string]string{}, shapes: map[string][]shape{},
		uploads: map[string]*upload{}}
	server := httptest.NewServer(s.handler())
	t.Cleanup(server.Close)
	s.URL = server.URL
	return s
}

func (s *Server) handler() http.Handler {
	mux := http.NewServeMux()
	const core = "/20160918"
	mux.HandleFunc("HEAD /n/{namespace}/b/{bucket}/o/{object...}", s.headObject)
	mux.HandleFunc("PUT /n/{namespace}/b/{bucket}/o/{object...}", s.putObject)
	s.routeMultipart(mux)
	mux.HandleFunc("GET "+core+"/images", s.listImages)
	mux.HandleFunc("POST "+core+"/images", s.createImage)
	mux.HandleFunc("GET "+core+"/images/{id}", s.getImage)
	mux.HandleFunc("GET "+core+"/workRequests/{id}", s.getWorkRequest)
	mux.HandleFunc("GET "+core+"/computeImageCapabilitySchemas", s.listSchemas)
	mux.HandleFunc("POST "+core+"/computeImageCapabilitySchemas", s.createSchema)
	mux.HandleFunc("GET "+core+"/computeImageCapabilitySchemas/{id}", s.getSchema)
	mux.HandleFunc("GET "+core+"/computeGlobalImageCapabilitySchemas", func(w http.ResponseWriter, r *http.Request) {
		// The first page is empty and points at the next one, so the
		// client must follow pagination to find the schema.
		if r.URL.Query().Get("page") == "" {
			w.Header().Set("opc-next-page", "global-schemas-2")
			reply(w, http.StatusOK, []map[string]string{})
			return
		}
		reply(w, http.StatusOK, []map[string]string{{"id": "ocid1.computeglobalimgcapschema.standin", "currentVersionName": "standin-v1"}})
	})
	mux.HandleFunc("GET "+core+"/images/{id}/shapes", s.listShapes)
	mux.HandleFunc("PUT "+core+"/images/{id}/shapes/{shape}", s.addShape)
	mux.HandleFunc("DELETE "+core+"/images/{id}/shapes/{shape}", s.removeShape)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Every SDK request is signed; an unsigned request is not the client
		// under test.
		if !strings.HasPrefix(r.Header.Get("Authorization"), "Signature ") {
			refuse(w, http.StatusUnauthorized, "NotAuthenticated", "unsigned request")
			return
		}
		s.mu.Lock()
		s.requests = append(s.requests, r.Method+" "+r.URL.Path)
		s.mu.Unlock()
		mux.ServeHTTP(w, r)
	})
}

func (s *Server) headObject(w http.ResponseWriter, r *http.Request) {
	s.mu.Lock()
	stored, ok := s.objects[objectKey(r)]
	s.mu.Unlock()
	if !ok {
		w.WriteHeader(http.StatusNotFound)
		return
	}
	for key, value := range stored.metadata {
		w.Header().Set("opc-meta-"+key, value)
	}
	w.Header().Set("Content-Length", fmt.Sprint(len(stored.data)))
	w.Header().Set("ETag", "standin")
	w.WriteHeader(http.StatusOK)
}

func (s *Server) putObject(w http.ResponseWriter, r *http.Request) {
	data, err := io.ReadAll(r.Body)
	if err != nil {
		refuse(w, http.StatusBadRequest, "InvalidParameter", err.Error())
		return
	}
	if want := r.Header.Get("Content-MD5"); want != "" && want != contentMD5(data) {
		refuse(w, http.StatusBadRequest, "InvalidContentMD5", "object MD5 mismatch")
		return
	}
	metadata := map[string]string{}
	for key, values := range r.Header {
		if name, ok := strings.CutPrefix(strings.ToLower(key), "opc-meta-"); ok && len(values) > 0 {
			metadata[name] = values[0]
		}
	}
	key := objectKey(r)
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, exists := s.objects[key]; exists && r.Header.Get("If-None-Match") == "*" {
		refuse(w, http.StatusPreconditionFailed, "IfNoneMatchFailed", "object exists")
		return
	}
	s.objects[key] = object{data: data, metadata: metadata}
	w.Header().Set("ETag", "standin")
	w.WriteHeader(http.StatusOK)
}

func (s *Server) find(id string) *image {
	for _, stored := range s.images {
		if stored.ID == id {
			return stored
		}
	}
	return nil
}

func (s *Server) listImages(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query()
	s.mu.Lock()
	defer s.mu.Unlock()
	matches := []image{}
	for _, stored := range s.images {
		if stored.CompartmentID == query.Get("compartmentId") && (query.Get("displayName") == "" || stored.DisplayName == query.Get("displayName")) {
			matches = append(matches, *stored)
		}
	}
	reply(w, http.StatusOK, matches)
}

type createImage struct {
	CompartmentID string            `json:"compartmentId"`
	DisplayName   string            `json:"displayName"`
	FreeformTags  map[string]string `json:"freeformTags"`
	LaunchMode    string            `json:"launchMode"`
	Source        struct {
		Type            string `json:"sourceType"`
		Namespace       string `json:"namespaceName"`
		Bucket          string `json:"bucketName"`
		Object          string `json:"objectName"`
		SourceImageType string `json:"sourceImageType"`
	} `json:"imageSourceDetails"`
}

func (s *Server) createImage(w http.ResponseWriter, r *http.Request) {
	var request createImage
	if err := json.UnmarshalRead(r.Body, &request); err != nil {
		refuse(w, http.StatusBadRequest, "InvalidParameter", err.Error())
		return
	}
	if r.Header.Get("opc-retry-token") == "" || request.Source.Type != "objectStorageTuple" || request.Source.SourceImageType != "QCOW2" || request.LaunchMode != "PARAVIRTUALIZED" {
		refuse(w, http.StatusBadRequest, "InvalidParameter", "unexpected CreateImage request")
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.objects[request.Source.Namespace+"/"+request.Source.Bucket+"/"+request.Source.Object]; !ok {
		refuse(w, http.StatusNotFound, "NotAuthorizedOrNotFound", "source object not found")
		return
	}
	id := s.imageID
	if len(s.images) > 0 {
		id = fmt.Sprintf("%s.%d", s.imageID, len(s.images))
	}
	created := &image{ID: id, CompartmentID: request.CompartmentID, DisplayName: request.DisplayName, State: "IMPORTING",
		Billable: BillableSizeGB, TimeCreated: s.created.Format(time.RFC3339), FreeformTags: request.FreeformTags}
	s.images = append(s.images, created)
	work := fmt.Sprintf("ocid1.coreservicesworkrequest.standin.%d", len(s.work)+1)
	s.work[work] = WorkRequestPolls
	s.workIDs[work] = id
	w.Header().Set("opc-work-request-id", work)
	reply(w, http.StatusOK, created)
}

func (s *Server) getImage(w http.ResponseWriter, r *http.Request) {
	s.mu.Lock()
	defer s.mu.Unlock()
	stored := s.find(r.PathValue("id"))
	if stored == nil {
		refuse(w, http.StatusNotFound, "NotAuthorizedOrNotFound", "image not found")
		return
	}
	reply(w, http.StatusOK, stored)
}

func (s *Server) getWorkRequest(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	s.mu.Lock()
	defer s.mu.Unlock()
	remaining, ok := s.work[id]
	if !ok {
		refuse(w, http.StatusNotFound, "NotAuthorizedOrNotFound", "work request not found")
		return
	}
	status := "SUCCEEDED"
	if remaining > 0 {
		status = "IN_PROGRESS"
		s.work[id] = remaining - 1
	} else if stored := s.find(s.workIDs[id]); stored != nil {
		stored.State = "AVAILABLE"
	}
	reply(w, http.StatusOK, map[string]any{"id": id, "operationType": "ImportImage", "status": status,
		"compartmentId": "standin", "percentComplete": 0, "timeAccepted": s.created.Format(time.RFC3339)})
}

func (s *Server) listSchemas(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query()
	s.mu.Lock()
	defer s.mu.Unlock()
	summaries := []map[string]string{}
	for _, stored := range s.schemas {
		if stored.CompartmentID == query.Get("compartmentId") && stored.ImageID == query.Get("imageId") {
			summaries = append(summaries, map[string]string{"id": stored.ID, "displayName": stored.DisplayName,
				"computeGlobalImageCapabilitySchemaVersionName": stored.Version, "timeCreated": stored.TimeCreated})
		}
	}
	reply(w, http.StatusOK, summaries)
}

func (s *Server) createSchema(w http.ResponseWriter, r *http.Request) {
	var request schema
	if err := json.UnmarshalRead(r.Body, &request); err != nil {
		refuse(w, http.StatusBadRequest, "InvalidParameter", err.Error())
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.find(request.ImageID) == nil {
		refuse(w, http.StatusNotFound, "NotAuthorizedOrNotFound", "image not found")
		return
	}
	request.ID = fmt.Sprintf("ocid1.computeimgcapschema.standin.%d", len(s.schemas)+1)
	request.TimeCreated = s.created.Format(time.RFC3339)
	s.schemas = append(s.schemas, request)
	reply(w, http.StatusOK, request)
}

func (s *Server) getSchema(w http.ResponseWriter, r *http.Request) {
	s.mu.Lock()
	defer s.mu.Unlock()
	for _, stored := range s.schemas {
		if stored.ID == r.PathValue("id") {
			reply(w, http.StatusOK, stored)
			return
		}
	}
	refuse(w, http.StatusNotFound, "NotAuthorizedOrNotFound", "schema not found")
}

func (s *Server) listShapes(w http.ResponseWriter, r *http.Request) {
	s.mu.Lock()
	defer s.mu.Unlock()
	entries := s.shapes[r.PathValue("id")]
	if entries == nil {
		entries = []shape{}
	}
	reply(w, http.StatusOK, entries)
}

func (s *Server) addShape(w http.ResponseWriter, r *http.Request) {
	var request struct {
		OCPU   *jsontext.Value `json:"ocpuConstraints,omitempty"`
		Memory *jsontext.Value `json:"memoryConstraints,omitempty"`
	}
	if err := json.UnmarshalRead(r.Body, &request); err != nil {
		refuse(w, http.StatusBadRequest, "InvalidParameter", err.Error())
		return
	}
	id, name := r.PathValue("id"), r.PathValue("shape")
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.find(id) == nil {
		refuse(w, http.StatusNotFound, "NotAuthorizedOrNotFound", "image not found")
		return
	}
	entry := shape{ImageID: id, Shape: name, OCPU: request.OCPU, Memory: request.Memory}
	entries := slices.DeleteFunc(s.shapes[id], func(existing shape) bool { return existing.Shape == name })
	s.shapes[id] = append(entries, entry)
	reply(w, http.StatusOK, entry)
}

func (s *Server) removeShape(w http.ResponseWriter, r *http.Request) {
	id, name := r.PathValue("id"), r.PathValue("shape")
	s.mu.Lock()
	defer s.mu.Unlock()
	s.shapes[id] = slices.DeleteFunc(s.shapes[id], func(existing shape) bool { return existing.Shape == name })
	w.WriteHeader(http.StatusNoContent)
}

var signingKey = sync.OnceValues(func() (string, error) {
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		return "", err
	}
	return string(pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(key)})), nil
})

func Client(endpoint, region string) (imageimport.API, error) {
	key, err := signingKey()
	if err != nil {
		return nil, err
	}
	provider := common.NewRawConfigurationProvider("ocid1.tenancy.oc1..standin", "ocid1.user.oc1..standin", region,
		"00:00:00:00:00:00:00:00:00:00:00:00:00:00:00:00", key, nil)
	factory, err := ociclient.New(provider, ociclient.Options{Region: region,
		Retry: ociclient.RetryOptions{MaxAttempts: 1}})
	if err != nil {
		return nil, err
	}
	return imageimport.NewClient(factory, endpoint)
}

// Importer returns an ImporterFactory whose importers drive the real SDK
// client against the stand-in at endpoint, polling every millisecond.
func Importer(endpoint string) imageimport.ImporterFactory {
	return func(region string) (imageimport.Importer, error) {
		client, err := Client(endpoint, region)
		if err != nil {
			return imageimport.Importer{}, err
		}
		return imageimport.Importer{Client: client, PollInterval: time.Millisecond, MaxPollInterval: 5 * time.Millisecond,
			AvailabilityTimeout: time.Minute}, nil
	}
}

func (i Importer) pause(ctx context.Context, delay time.Duration) error {
	if i.Pause != nil {
		return i.Pause(ctx, delay)
	}
	timer := time.NewTimer(delay)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}

var liveImageStates = []string{"IMPORTING", "PROVISIONING", "AVAILABLE"}

func (i Importer) FindImage(ctx context.Context, compartment, name string) (*Image, error) {
	images, err := i.Client.ListImages(ctx, compartment, name)
	if err != nil {
		return nil, err
	}
	var live *Image
	for _, image := range images {
		if slices.Contains(liveImageStates, image.LifecycleState) {
			if live != nil {
				return nil, fmt.Errorf("more than one live image is named %s", name)
			}
			live = &image
		}
	}
	return live, nil
}

// WaitAvailable waits for the import work request, when known, and then for
// the image to report AVAILABLE. Polls start at PollInterval (5s) and double
// up to MaxPollInterval so short imports finish quickly without hammering OCI
// during long ones.
func (i Importer) WaitAvailable(ctx context.Context, id, workRequest string) (Image, error) {
	timeout := i.AvailabilityTimeout
	if timeout <= 0 {
		timeout = 45 * time.Minute
	}
	interval := i.PollInterval
	if interval <= 0 {
		interval = 5 * time.Second
	}
	ceiling := i.MaxPollInterval
	if ceiling <= 0 {
		ceiling = 60 * time.Second
	}
	ctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	for {
		if workRequest != "" {
			status, err := i.Client.GetWorkRequest(ctx, workRequest)
			if err != nil {
				return Image{}, err
			}
			switch status {
			case WorkRequestSucceeded:
				workRequest = ""
			case WorkRequestAccepted, WorkRequestInProgress:
			default:
				return Image{}, fmt.Errorf("image %s import work request %s ended %s", id, workRequest, status)
			}
		}
		if workRequest == "" {
			image, err := i.Client.GetImage(ctx, id)
			if err != nil {
				return Image{}, err
			}
			switch image.LifecycleState {
			case "AVAILABLE":
				return image, nil
			case "IMPORTING", "PROVISIONING":
			default:
				return Image{}, fmt.Errorf("image %s entered %v", id, image.LifecycleState)
			}
		}
		if err := i.pause(ctx, interval); err != nil {
			return Image{}, fmt.Errorf("image %s did not become AVAILABLE: %w", id, err)
		}
		interval = min(interval*2, ceiling)
	}
}

func (i Importer) EnsureCapabilities(ctx context.Context, compartment, id, name string) (CapabilitySchema, error) {
	ids, err := i.Client.ListCapabilitySchemas(ctx, compartment, id)
	if err != nil {
		return CapabilitySchema{}, err
	}
	var schema CapabilitySchema
	if len(ids) > 0 {
		if ids[0] == "" {
			return CapabilitySchema{}, errors.New("OCI capability schema has no id")
		}
		schema, err = i.Client.GetCapabilitySchema(ctx, ids[0])
		if err != nil {
			return CapabilitySchema{}, err
		}
	} else {
		version, err := i.Client.GlobalCapabilitySchemaVersion(ctx)
		if err != nil {
			return CapabilitySchema{}, err
		}
		if version == "" {
			return CapabilitySchema{}, errors.New("global schema has no version")
		}
		runes := []rune(name)
		if len(runes) > 255 {
			name = string(runes[:255])
		}
		schema, err = i.Client.CreateCapabilitySchema(ctx, compartment, id, name, version, Capabilities())
		if err != nil {
			return CapabilitySchema{}, err
		}
	}
	if schema.ID == "" {
		return CapabilitySchema{}, errors.New("OCI capability schema has no id")
	}
	for key, expected := range Capabilities() {
		actual, ok := schema.Data[key]
		if !ok || !actual.equal(expected) {
			return CapabilitySchema{}, fmt.Errorf("image capability %s differs from the launch contract", key)
		}
	}
	return schema, nil
}

func (i Importer) EnsureShapes(ctx context.Context, id string) ([]ShapeEntry, error) {
	entries, err := i.Client.ListShapes(ctx, id)
	if err != nil {
		return nil, err
	}
	index := slices.IndexFunc(entries, func(entry ShapeEntry) bool { return entry.Shape == A1Shape })
	if index < 0 || !a1Constraints(entries[index]) {
		if err := i.Client.AddShape(ctx, id, ShapeEntry{Shape: A1Shape, OCPU: new(a1OCPU), MemoryGB: new(a1Memory)}); err != nil {
			return nil, err
		}
	}
	for _, entry := range entries {
		if entry.Shape == "" {
			return nil, errors.New("shape compatibility row lacks shape")
		}
		if entry.Shape != A1Shape && !strings.HasSuffix(entry.Shape, ".Generic") {
			if err := i.Client.RemoveShape(ctx, id, entry.Shape); err != nil {
				return nil, err
			}
		}
	}
	entries, err = i.Client.ListShapes(ctx, id)
	if err != nil {
		return nil, err
	}
	found := false
	for _, entry := range entries {
		if entry.Shape == "" {
			return nil, errors.New("shape compatibility row lacks shape")
		}
		if entry.Shape == A1Shape {
			found = true
			if !a1Constraints(entry) {
				return nil, errors.New("image A1 constraints differ from the launch contract")
			}
		}
		if entry.Shape != A1Shape && !strings.HasSuffix(entry.Shape, ".Generic") {
			return nil, errors.New("image shape compatibility is not A1-only")
		}
	}
	if !found {
		return nil, errors.New("image shape compatibility is not A1-only")
	}
	return entries, nil
}

func (o Options) validate() error {
	for key, value := range map[string]string{"qcow2": o.QCOW2, "sha256": o.SHA256, "compartment-id": o.Compartment, "namespace": o.Namespace, "bucket": o.Bucket, "display-name": o.DisplayName, "out": o.Out} {
		if value == "" {
			return fmt.Errorf("--%s is required", key)
		}
	}
	if len(o.Regions) == 0 {
		return errors.New("--region is required")
	}
	seen := map[string]bool{}
	for _, region := range o.Regions {
		if !catalog.IsOCIRegion(region) {
			return fmt.Errorf("--region %q is not a catalog OCI region", region)
		}
		if seen[region] {
			return fmt.Errorf("--region %q is repeated", region)
		}
		seen[region] = true
	}
	if o.PartSizeMiB < 0 || o.PartSizeMiB > maxPartSizeMiB || o.UploadParallelism < 0 || o.UploadParallelism > maxUploadParallelism {
		return errors.New("upload part size or parallelism is out of bounds")
	}
	return nil
}

func verifyDigest(path, want string) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	h := sha256.New()
	_, err = io.Copy(h, f)
	closeErr := f.Close()
	if err != nil {
		return err
	}
	if closeErr != nil {
		return closeErr
	}
	if hex.EncodeToString(h.Sum(nil)) != want {
		return errors.New("QCOW2 bytes differ from the expected SHA-256")
	}
	return nil
}

// ImportRegions verifies the QCOW2 digest once, before any cloud effect, then
// imports into every region concurrently. A single region writes the
// terrascale.oci.image-import.v1 record unchanged; several regions write a
// terrascale.oci.image-import-set.v1 record keyed by region. Progress is
// checkpointed as regions finish, including successful imports on fleet failure.
func ImportRegions(ctx context.Context, o Options, out io.Writer, importer func(region string) (Importer, error)) (map[string]any, error) {
	if ctx.Err() != nil {
		return nil, ctx.Err()
	}
	if err := o.validate(); err != nil {
		return nil, err
	}
	if err := verifyDigest(o.QCOW2, o.SHA256); err != nil {
		return nil, err
	}
	var (
		mu          sync.Mutex
		wg          sync.WaitGroup
		records     = make(map[string]map[string]any, len(o.Regions))
		errs        = make([]error, len(o.Regions))
		done        = make([]bool, len(o.Regions))
		checkpoints []error
	)
	result := func() map[string]any {
		if len(o.Regions) == 1 && records[o.Regions[0]] != nil {
			return records[o.Regions[0]]
		}
		regions := make(map[string]any, len(records))
		for region, record := range records {
			regions[region] = record
		}
		r := map[string]any{"schema": "terrascale.oci.image-import-set.v1", "qcow2_sha256": o.SHA256, "display_name": o.DisplayName, "regions": regions}
		failures := map[string]string{}
		var pending []string
		for index, region := range o.Regions {
			if !done[index] {
				pending = append(pending, region)
			}
			if errs[index] != nil {
				failures[region] = errs[index].Error()
			}
		}
		if len(failures) > 0 {
			r["errors"] = failures
		}
		if len(pending) > 0 {
			r["pending"] = pending
		}
		return r
	}
	if err := writeImportCheckpoint(o.Out, result()); err != nil {
		return nil, err
	}
	logf := func(format string, args ...any) {
		mu.Lock()
		defer mu.Unlock()
		_, _ = fmt.Fprintf(out, format, args...)
	}
	semaphore := make(chan struct{}, 3)
	for index, region := range o.Regions {
		semaphore <- struct{}{}
		wg.Go(func() {
			defer func() { <-semaphore }()
			var record map[string]any
			regional, err := importer(region)
			if err == nil {
				record, err = regional.importVerified(ctx, o, func(format string, args ...any) {
					if len(o.Regions) > 1 {
						format = region + ": " + format
					}
					logf(format, args...)
				})
			}
			mu.Lock()
			defer mu.Unlock()
			done[index] = true
			if err != nil {
				errs[index] = fmt.Errorf("%s: %w", region, err)
			} else {
				records[region] = record
			}
			if err := writeImportCheckpoint(o.Out, result()); err != nil {
				checkpoints = append(checkpoints, fmt.Errorf("checkpoint %s: %w", region, err))
			}
		})
	}
	wg.Wait()
	final := result()
	b, err := json.Marshal(final, json.Deterministic(true))
	if err != nil {
		return final, errors.Join(errors.Join(errs...), errors.Join(checkpoints...), err)
	}
	_, err = fmt.Fprintln(out, string(b))
	return final, errors.Join(errors.Join(errs...), errors.Join(checkpoints...), err)
}

func writeImportCheckpoint(path string, record map[string]any) error {
	b, err := json.Marshal(record, json.Deterministic(true))
	if err != nil {
		return err
	}
	f, err := os.CreateTemp(filepath.Dir(path), ".image-import-*")
	if err != nil {
		return err
	}
	defer os.Remove(f.Name())
	if _, err = f.Write(append(b, '\n')); err == nil {
		err = f.Sync()
	}
	if err == nil {
		err = f.Chmod(0644)
	}
	if closeErr := f.Close(); err == nil {
		err = closeErr
	}
	if err != nil {
		return err
	}
	if err := os.Rename(f.Name(), path); err != nil {
		return err
	}
	dir, err := os.Open(filepath.Dir(path))
	if err != nil {
		return err
	}
	defer dir.Close()
	return dir.Sync()
}

// Import imports into this importer's single region.

func (i Importer) importVerified(ctx context.Context, o Options, logf func(string, ...any)) (map[string]any, error) {
	objectName := "images/" + o.SHA256 + ".qcow2"
	image, err := i.FindImage(ctx, o.Compartment, o.DisplayName)
	if err != nil {
		return nil, err
	}
	// Display names are static (gru-1-arm64), so a live image of this name
	// may hold another QCOW2. Resume only the import of these exact bytes.
	if image != nil && image.SHA256 != o.SHA256 {
		return nil, fmt.Errorf("live image %s is named %s but holds QCOW2 %q, not %s; retire it before importing",
			image.ID, o.DisplayName, image.SHA256, o.SHA256)
	}
	workRequest := ""
	if image == nil {
		exists, metadata, err := i.Client.HeadObject(ctx, o.Namespace, o.Bucket, objectName)
		if err != nil {
			return nil, err
		}
		if exists && metadata["sha256"] != "" && metadata["sha256"] != o.SHA256 {
			return nil, fmt.Errorf("object %s carries a different sha256 metadata value", objectName)
		}
		if !exists {
			logf("uploading %s\n", objectName)
			partSize := o.PartSizeMiB
			if partSize == 0 {
				partSize = defaultPartSizeMiB
			}
			parallelism := o.UploadParallelism
			if parallelism == 0 {
				parallelism = defaultUploadParallelism
			}
			if err := i.Client.UploadObject(ctx, UploadRequest{Namespace: o.Namespace, Bucket: o.Bucket, Object: objectName,
				Path: o.QCOW2, SHA256: o.SHA256, Metadata: map[string]string{"sha256": o.SHA256},
				PartSize: int64(partSize) << 20, Parallelism: parallelism}); err != nil {
				return nil, err
			}
		}
		logf("importing image\n")
		created, request, err := i.Client.ImportImage(ctx, ImportRequest{Compartment: o.Compartment, Namespace: o.Namespace,
			Bucket: o.Bucket, Object: objectName, DisplayName: o.DisplayName, SHA256: o.SHA256})
		if err != nil {
			return nil, err
		}
		image, workRequest = &created, request
	}
	if image.ID == "" {
		return nil, errors.New("OCI image has no id")
	}
	id := image.ID
	available, err := i.WaitAvailable(ctx, id, workRequest)
	if err != nil {
		return nil, err
	}
	schema, err := i.EnsureCapabilities(ctx, o.Compartment, id, o.DisplayName)
	if err != nil {
		return nil, err
	}
	shapes, err := i.EnsureShapes(ctx, id)
	if err != nil {
		return nil, err
	}
	names := make([]string, 0, len(shapes))
	for _, entry := range shapes {
		names = append(names, entry.Shape)
	}
	slices.Sort(names)
	var billable any
	if available.BillableSizeGB != nil {
		billable = *available.BillableSizeGB
	}
	return map[string]any{"schema": "terrascale.oci.image-import.v1", "image_id": id, "display_name": o.DisplayName,
		"qcow2_sha256": o.SHA256, "compartment_id": o.Compartment, "object": o.Namespace + "/" + o.Bucket + "/" + objectName,
		"billable_size_gb": billable, "capability_schema_id": schema.ID, "shapes": names}, nil
}

func NewClient(factory *ociclient.Factory, endpoint string) (API, error) {
	return newSDKClient(factory, endpoint)
}

func newSDKClient(factory *ociclient.Factory, endpoint string) (*sdkClient, error) {
	compute, err := factory.Compute()
	if err != nil {
		return nil, err
	}
	objects, err := factory.ObjectStorage()
	if err != nil {
		return nil, err
	}
	work, err := factory.WorkRequests()
	if err != nil {
		return nil, err
	}
	ociclient.PinHost(&compute.BaseClient, endpoint)
	ociclient.PinHost(&objects.BaseClient, endpoint)
	ociclient.PinHost(&work.BaseClient, endpoint)
	return &sdkClient{compute: compute, objects: objects, workRequest: work,
		uploadRetry: ociclient.IdempotentPutRetryPolicy(ociclient.RetryOptions{})}, nil
}

func page(next *string) (*string, bool) {
	if next == nil || *next == "" {
		return nil, false
	}
	return next, true
}

func (c *sdkClient) ListImages(ctx context.Context, compartment, displayName string) ([]Image, error) {
	var images []Image
	var cursor *string
	for range maxPages {
		response, err := c.compute.ListImages(ociclient.RequestContext(ctx), core.ListImagesRequest{CompartmentId: new(compartment),
			DisplayName: new(displayName), Page: cursor})
		if err != nil {
			return nil, fmt.Errorf("list OCI images: %w", err)
		}
		for _, item := range response.Items {
			images = append(images, image(item))
		}
		var more bool
		if cursor, more = page(response.OpcNextPage); !more {
			return images, nil
		}
	}
	return nil, errors.New("OCI image list exceeds its page bound")
}

func image(item core.Image) Image {
	return Image{ID: deref(item.Id), LifecycleState: string(item.LifecycleState), BillableSizeGB: item.BillableSizeInGBs,
		SHA256: item.FreeformTags[SHA256Tag]}
}

func deref(value *string) string {
	if value == nil {
		return ""
	}
	return *value
}

func (c *sdkClient) GetImage(ctx context.Context, id string) (Image, error) {
	response, err := c.compute.GetImage(ociclient.RequestContext(ctx), core.GetImageRequest{ImageId: new(id)})
	if err != nil {
		return Image{}, fmt.Errorf("get OCI image: %w", err)
	}
	return image(response.Image), nil
}

func (c *sdkClient) HeadObject(ctx context.Context, namespace, bucket, object string) (bool, map[string]string, error) {
	response, err := c.objects.HeadObject(ociclient.RequestContext(ctx), objectstorage.HeadObjectRequest{NamespaceName: new(namespace),
		BucketName: new(bucket), ObjectName: new(object)})
	if err != nil {
		if serviceErr, ok := common.IsServiceError(err); ok && serviceErr.GetHTTPStatusCode() == http.StatusNotFound {
			return false, nil, nil
		}
		return false, nil, fmt.Errorf("head OCI object: %w", err)
	}
	return true, response.OpcMeta, nil
}

func (c *sdkClient) UploadObject(ctx context.Context, request UploadRequest) error {
	return c.streamUpload(ctx, request)
}

func (c *sdkClient) ImportImage(ctx context.Context, request ImportRequest) (Image, string, error) {
	response, err := c.compute.CreateImage(ociclient.RequestContext(ctx), core.CreateImageRequest{
		CreateImageDetails: core.CreateImageDetails{
			CompartmentId: new(request.Compartment), DisplayName: new(request.DisplayName),
			FreeformTags: map[string]string{SHA256Tag: request.SHA256},
			LaunchMode:   core.CreateImageDetailsLaunchModeParavirtualized,
			ImageSourceDetails: core.ImageSourceViaObjectStorageTupleDetails{
				NamespaceName: new(request.Namespace), BucketName: new(request.Bucket), ObjectName: new(request.Object),
				SourceImageType: core.ImageSourceDetailsSourceImageTypeQcow2,
				OperatingSystem: new("Custom"), OperatingSystemVersion: new("Custom"),
			},
		},
		// A retry token lets the shared policy replay a lost CreateImage safely.
		OpcRetryToken: new(common.RetryToken()),
	})
	if err != nil {
		return Image{}, "", fmt.Errorf("import OCI image: %w", err)
	}
	return image(response.Image), deref(response.OpcWorkRequestId), nil
}

func (c *sdkClient) GetWorkRequest(ctx context.Context, id string) (WorkRequestStatus, error) {
	response, err := c.workRequest.GetWorkRequest(ociclient.RequestContext(ctx), workrequests.GetWorkRequestRequest{WorkRequestId: new(id)})
	if err != nil {
		return "", fmt.Errorf("get OCI work request: %w", err)
	}
	return WorkRequestStatus(response.Status), nil
}

func (c *sdkClient) ListCapabilitySchemas(ctx context.Context, compartment, imageID string) ([]string, error) {
	var ids []string
	var cursor *string
	for range maxPages {
		response, err := c.compute.ListComputeImageCapabilitySchemas(ociclient.RequestContext(ctx), core.ListComputeImageCapabilitySchemasRequest{
			CompartmentId: new(compartment), ImageId: new(imageID), Page: cursor})
		if err != nil {
			return nil, fmt.Errorf("list OCI image capability schemas: %w", err)
		}
		for _, item := range response.Items {
			ids = append(ids, deref(item.Id))
		}
		var more bool
		if cursor, more = page(response.OpcNextPage); !more {
			return ids, nil
		}
	}
	return nil, errors.New("OCI capability schema list exceeds its page bound")
}

func capabilitySchema(id *string, data map[string]core.ImageCapabilitySchemaDescriptor) CapabilitySchema {
	schema := CapabilitySchema{ID: deref(id), Data: make(map[string]Capability, len(data))}
	for key, descriptor := range data {
		switch value := descriptor.(type) {
		case core.EnumStringImageCapabilitySchemaDescriptor:
			schema.Data[key] = Capability{Values: value.Values, Default: deref(value.DefaultValue)}
		case core.BooleanImageCapabilitySchemaDescriptor:
			schema.Data[key] = Capability{Boolean: true, BoolDefault: value.DefaultValue != nil && *value.DefaultValue}
		}
	}
	return schema
}

func (c *sdkClient) GetCapabilitySchema(ctx context.Context, id string) (CapabilitySchema, error) {
	response, err := c.compute.GetComputeImageCapabilitySchema(ociclient.RequestContext(ctx), core.GetComputeImageCapabilitySchemaRequest{
		ComputeImageCapabilitySchemaId: new(id)})
	if err != nil {
		return CapabilitySchema{}, fmt.Errorf("get OCI image capability schema: %w", err)
	}
	return capabilitySchema(response.Id, response.SchemaData), nil
}

func (c *sdkClient) GlobalCapabilitySchemaVersion(ctx context.Context) (string, error) {
	// The first listed schema is used, as with the CLI's --all listing; a
	// first page that is empty but has more pages is followed.
	var cursor *string
	for range maxPages {
		response, err := c.compute.ListComputeGlobalImageCapabilitySchemas(ociclient.RequestContext(ctx),
			core.ListComputeGlobalImageCapabilitySchemasRequest{Page: cursor})
		if err != nil {
			return "", fmt.Errorf("list OCI global image capability schemas: %w", err)
		}
		if len(response.Items) > 0 {
			return deref(response.Items[0].CurrentVersionName), nil
		}
		var more bool
		if cursor, more = page(response.OpcNextPage); !more {
			return "", errors.New("OCI returned no global capability schema")
		}
	}
	return "", errors.New("OCI global capability schema list exceeds its page bound")
}

func (c *sdkClient) CreateCapabilitySchema(ctx context.Context, compartment, imageID, displayName, version string, data map[string]Capability) (CapabilitySchema, error) {
	descriptors := make(map[string]core.ImageCapabilitySchemaDescriptor, len(data))
	for key, capability := range data {
		if capability.Boolean {
			descriptors[key] = core.BooleanImageCapabilitySchemaDescriptor{Source: core.ImageCapabilitySchemaDescriptorSourceImage,
				DefaultValue: new(capability.BoolDefault)}
			continue
		}
		descriptors[key] = core.EnumStringImageCapabilitySchemaDescriptor{Source: core.ImageCapabilitySchemaDescriptorSourceImage,
			Values: capability.Values, DefaultValue: new(capability.Default)}
	}
	response, err := c.compute.CreateComputeImageCapabilitySchema(ociclient.RequestContext(ctx), core.CreateComputeImageCapabilitySchemaRequest{
		CreateComputeImageCapabilitySchemaDetails: core.CreateComputeImageCapabilitySchemaDetails{
			CompartmentId: new(compartment), ImageId: new(imageID), DisplayName: new(displayName),
			ComputeGlobalImageCapabilitySchemaVersionName: new(version), SchemaData: descriptors,
		},
		OpcRetryToken: new(common.RetryToken()),
	})
	if err != nil {
		return CapabilitySchema{}, fmt.Errorf("create OCI image capability schema: %w", err)
	}
	return capabilitySchema(response.Id, response.SchemaData), nil
}

func (c *sdkClient) ListShapes(ctx context.Context, imageID string) ([]ShapeEntry, error) {
	var entries []ShapeEntry
	var cursor *string
	for range maxPages {
		response, err := c.compute.ListImageShapeCompatibilityEntries(ociclient.RequestContext(ctx), core.ListImageShapeCompatibilityEntriesRequest{
			ImageId: new(imageID), Page: cursor})
		if err != nil {
			return nil, fmt.Errorf("list OCI image shape compatibility: %w", err)
		}
		for _, item := range response.Items {
			entry := ShapeEntry{Shape: deref(item.Shape)}
			if item.OcpuConstraints != nil && item.OcpuConstraints.Min != nil && item.OcpuConstraints.Max != nil {
				entry.OCPU = &Range{Min: *item.OcpuConstraints.Min, Max: *item.OcpuConstraints.Max}
			}
			if item.MemoryConstraints != nil && item.MemoryConstraints.MinInGBs != nil && item.MemoryConstraints.MaxInGBs != nil {
				entry.MemoryGB = &Range{Min: *item.MemoryConstraints.MinInGBs, Max: *item.MemoryConstraints.MaxInGBs}
			}
			entries = append(entries, entry)
		}
		var more bool
		if cursor, more = page(response.OpcNextPage); !more {
			return entries, nil
		}
	}
	return nil, errors.New("OCI shape compatibility list exceeds its page bound")
}

func (c *sdkClient) AddShape(ctx context.Context, imageID string, entry ShapeEntry) error {
	details := core.AddImageShapeCompatibilityEntryDetails{}
	if entry.OCPU != nil {
		details.OcpuConstraints = &core.ImageOcpuConstraints{Min: new(entry.OCPU.Min), Max: new(entry.OCPU.Max)}
	}
	if entry.MemoryGB != nil {
		details.MemoryConstraints = &core.ImageMemoryConstraints{MinInGBs: new(entry.MemoryGB.Min), MaxInGBs: new(entry.MemoryGB.Max)}
	}
	_, err := c.compute.AddImageShapeCompatibilityEntry(ociclient.RequestContext(ctx), core.AddImageShapeCompatibilityEntryRequest{
		ImageId: new(imageID), ShapeName: new(entry.Shape), AddImageShapeCompatibilityEntryDetails: details})
	if err != nil {
		return fmt.Errorf("add OCI image shape compatibility: %w", err)
	}
	return nil
}

func (c *sdkClient) RemoveShape(ctx context.Context, imageID, shape string) error {
	_, err := c.compute.RemoveImageShapeCompatibilityEntry(ociclient.RequestContext(ctx), core.RemoveImageShapeCompatibilityEntryRequest{
		ImageId: new(imageID), ShapeName: new(shape)})
	if err != nil {
		return fmt.Errorf("remove OCI image shape compatibility: %w", err)
	}
	return nil
}

func (c *sdkClient) streamUpload(ctx context.Context, request UploadRequest) error {
	if len(request.SHA256) != sha256.Size*2 {
		return errors.New("upload requires the expected SHA-256")
	}
	if request.PartSize < 1 || request.Parallelism < 1 {
		return errors.New("upload part size and parallelism must be positive")
	}
	file, err := os.Open(request.Path)
	if err != nil {
		return fmt.Errorf("open QCOW2: %w", err)
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return fmt.Errorf("stat QCOW2: %w", err)
	}
	parts := &partReader{file: file, partSize: request.PartSize, expected: info.Size()}
	digest := sha256.New()
	first, release, err := parts.next(ctx)
	if err != nil {
		return err
	}
	if int64(len(first)) < request.PartSize {
		defer release()
		digest.Write(first)
		if err := matches(digest, request.SHA256); err != nil {
			return err
		}
		sum := md5.Sum(first)
		_, err := c.objects.PutObject(ociclient.RequestContext(ctx), objectstorage.PutObjectRequest{NamespaceName: new(request.Namespace),
			BucketName: new(request.Bucket), ObjectName: new(request.Object), ContentLength: new(int64(len(first))),
			PutObjectBody: io.NopCloser(bytes.NewReader(first)), IfNoneMatch: new("*"), OpcMeta: request.Metadata,
			ContentMD5: new(base64.StdEncoding.EncodeToString(sum[:]))})
		if err != nil {
			return fmt.Errorf("upload OCI object: %w", err)
		}
		return nil
	}
	return c.multipartUpload(ctx, request, parts, digest, first, release)
}

// partReader reads the QCOW2 sequentially in parts. Buffers are sized by
// the bytes the file was stated to have left (plus one, so growth is still
// read and fails the digest), never by the part size alone: a small file
// with a huge configured part size does not allocate the part size.
type partReader struct {
	file     io.Reader
	partSize int64
	expected int64
	offset   int64
}

// next reads the next part after reserving its buffer from the process
// budget. release returns the reservation.
func (p *partReader) next(ctx context.Context) ([]byte, func(), error) {
	size := min(p.partSize, max(p.expected-p.offset, 0)+1)
	weight := min(size, uploadBufferBudget)
	if err := uploadBuffers.Acquire(ctx, weight); err != nil {
		return nil, nil, err
	}
	release := sync.OnceFunc(func() { uploadBuffers.Release(weight) })
	buffer := make([]byte, size)
	n, err := io.ReadFull(p.file, buffer)
	if err != nil && !errors.Is(err, io.EOF) && !errors.Is(err, io.ErrUnexpectedEOF) {
		release()
		return nil, nil, fmt.Errorf("read QCOW2: %w", err)
	}
	p.offset += int64(n)
	return buffer[:n], release, nil
}

func matches(digest hash.Hash, want string) error {
	if hex.EncodeToString(digest.Sum(nil)) != want {
		return ErrUploadDigestMismatch
	}
	return nil
}

func contentMD5(data []byte) string {
	sum := md5.Sum(data)
	return base64.StdEncoding.EncodeToString(sum[:])
}

