// Env names the test tier of the current run.
const Env = "TS_TEST_TIER"

// QualificationTier is the Env value of a pre-deploy qualification run.
const QualificationTier = "qualification"

// Qualifying reports whether this run is a T2 qualification run.
func Qualifying() bool { return os.Getenv(Env) == QualificationTier }

// Integration marks a T1 test: a multi-process lab or a slow end-to-end
// contract whose invariants T0 already covers with a single-process test.
// It skips under go test -short.
func Integration(t testing.TB) {
	t.Helper()
	if testing.Short() {
		t.Skip("integration tier: runs without -short on pushes to develop and main")
	}
}

// Qualification marks a T2 test that needs real infrastructure named by
// environment variables, and returns their values in order. When any of them
// is unset or empty the test skips, except in a qualification run, where it
// fails: the fixture the gate promised is missing.
func Qualification(t testing.TB, envs ...string) []string {
	t.Helper()
	if len(envs) == 0 {
		t.Fatal("tier.Qualification needs the environment variables that supply its fixture")
	}
	values := make([]string, len(envs))
	var missing []string
	for i, name := range envs {
		values[i] = os.Getenv(name)
		if values[i] == "" {
			missing = append(missing, name)
		}
	}
	if len(missing) > 0 {
		Unavailable(t, "qualification fixture not supplied: set %s", strings.Join(missing, ", "))
	}
	return values
}

// Unavailable reports that a T2 fixture is missing for a reason the caller
// determined itself, such as an opt-in that needs one of several variables.
// It skips the test, or fails it in a qualification run.
func Unavailable(t testing.TB, format string, args ...any) {
	t.Helper()
	if Qualifying() {
		t.Fatalf(Env+"="+QualificationTier+": "+format, args...)
	}
	t.Skipf(format, args...)
}

func newSDKCloud(region string) (Cloud, error) {
	factory, err := ociclient.OperatorConfig(region)
	if err != nil {
		return nil, err
	}
	compute, err := factory.Compute()
	if err != nil {
		return nil, err
	}
	objects, err := factory.ObjectStorage()
	if err != nil {
		return nil, err
	}
	// OCI accepts IAM writes only in the tenancy's home region, GRU's.
	home, err := ociclient.OperatorConfig(catalog.OCIRegion(catalog.Bootstrap))
	if err != nil {
		return nil, err
	}
	iam, err := home.Identity()
	if err != nil {
		return nil, err
	}
	return &sdkCloud{compute: compute, objects: objects, identity: iam}, nil
}

// maxPages bounds every paginated list so a misbehaving endpoint cannot loop.
const maxPages = 256

func instance(item core.Instance) Instance {
	image := deref(item.ImageId)
	if source, ok := item.SourceDetails.(core.InstanceSourceViaImageDetails); ok {
		image = deref(source.ImageId)
	}
	launched := Instance{ID: deref(item.Id), DisplayName: deref(item.DisplayName), LifecycleState: string(item.LifecycleState),
		CompartmentID: deref(item.CompartmentId), AvailabilityDomain: deref(item.AvailabilityDomain),
		FaultDomain: deref(item.FaultDomain), Shape: deref(item.Shape), ImageID: image,
		Metadata: item.Metadata, FreeformTags: item.FreeformTags}
	if config := item.ShapeConfig; config != nil && config.Ocpus != nil && config.MemoryInGBs != nil {
		launched.OCPUs, launched.MemoryInGBs = *config.Ocpus, *config.MemoryInGBs
	}
	return launched
}

func (c *sdkCloud) GetInstance(ctx context.Context, id string) (Instance, error) {
	response, err := c.compute.GetInstance(ctx, core.GetInstanceRequest{InstanceId: &id})
	if err != nil {
		return Instance{}, fmt.Errorf("get OCI instance: %w", err)
	}
	return instance(response.Instance), nil
}

func (c *sdkCloud) ListInstances(ctx context.Context, compartment string) ([]Instance, error) {
	var instances []Instance
	var page *string
	for range maxPages {
		response, err := c.compute.ListInstances(ctx, core.ListInstancesRequest{CompartmentId: &compartment, Page: page})
		if err != nil {
			return nil, fmt.Errorf("list OCI instances: %w", err)
		}
		for _, item := range response.Items {
			instances = append(instances, instance(item))
		}
		if response.OpcNextPage == nil || *response.OpcNextPage == "" {
			return instances, nil
		}
		page = response.OpcNextPage
	}
	return nil, errors.New("OCI instance list exceeds its page bound")
}

func OperatorConfig(region string) (*Factory, error) {
	return New(common.DefaultConfigProvider(), Options{Region: region})
}

func (f *Factory) Compute() (core.ComputeClient, error) {
	client, err := core.NewComputeClientWithConfigurationProvider(f.provider)
	if err != nil {
		return client, fmt.Errorf("create OCI Compute client: %w", err)
	}
	client.SetRegion(f.region)
	f.Configure(&client.BaseClient, ServiceCompute)
	return client, nil
}

func Validate(name string) error {
	match := nodeScheme.FindStringSubmatch(name)
	if match == nil {
		match = scheme.FindStringSubmatch(name)
	}
	if match == nil || !catalog.IsCell(strings.ToUpper(match[1])) {
		return fmt.Errorf("%w: %q", ErrName, name)
	}
	return nil
}

// Entry binds one logical product cell to its OCI region identifier.
type Entry struct {
	// Cell is the upper-case product region code, for example GRU.
	Cell string
	// OCIRegion is the canonical OCI region identifier, for example sa-saopaulo-1.
	OCIRegion string
	// OCIRegionKey is the OCI region key a tenancy subscribes with, for
	// example SJC for us-sanjose-1; it differs from the product cell code.
	OCIRegionKey string
	// City, Country (ISO 3166-1 alpha-2), Latitude and Longitude are display
	// metadata for operator views (the dashboard world map) and the cell's
	// Atlas region entry. They authorize nothing.
	City                string
	Country             string
	Latitude, Longitude float64
}

// Name is the lower-case cell token used in NATS subjects and host descriptors.
func (e Entry) Name() string { return strings.ToLower(e.Cell) }

