type policyCloud struct {
	Cloud
	statements []string
	etag       string
	updated    [][]string
	matched    []string
	objects    map[string][]byte
	reads      int
}

func (p *policyCloud) PolicyStatements(context.Context, string) ([]string, string, error) {
	return p.statements, p.etag, nil
}
func (p *policyCloud) ReplacePolicyStatements(_ context.Context, _ string, etag string, statements []string) error {
	p.updated, p.matched = append(p.updated, statements), append(p.matched, etag)
	return nil
}
func (p *policyCloud) GetObject(_ context.Context, _, _, name string) ([]byte, bool, error) {
	p.reads++
	if p.reads == 1 {
		return nil, false, errors.New("transient read failure")
	}
	data, ok := p.objects[name]
	return data, ok, nil
}

func (a *Attempt) controllerObjectGrants(plan Object) {
	ids := object(plan["resource_ids"])
	expected, e := ociregion.RequiredControllerStatements(plan, ids, a.Prefix)
	a.fail(e)
	if a.err != nil {
		return
	}
	cloud := a.cloud("GetPolicy")
	if cloud == nil {
		return
	}
	policyID := str(ids, "controller_policy")
	statements, etag, e := cloud.PolicyStatements(a.ctx, policyID)
	a.fail(e)
	if a.err != nil || slices.Equal(statements, expected) {
		return
	}
	// The replacement is conditional on the version just read; without an
	// ETag it would silently overwrite a concurrent policy change.
	if etag == "" {
		a.fail(fmt.Errorf("OCI policy %s read returned no ETag; refusing an unconditional update", policyID))
		return
	}
	if cloud = a.cloud("UpdatePolicy"); cloud != nil {
		a.fail(cloud.ReplacePolicyStatements(a.ctx, policyID, etag, expected))
	}
	if a.err == nil {
		fmt.Fprintln(a.Out, "controller object grants now target prefix", a.Prefix, "- waiting for IAM propagation")
		a.fail(a.Sleep(a.ctx, time.Minute))
	}
}

func (c *sdkCloud) PolicyStatements(ctx context.Context, policyID string) ([]string, string, error) {
	response, err := c.identity.GetPolicy(ctx, identity.GetPolicyRequest{PolicyId: &policyID})
	if err != nil {
		return nil, "", fmt.Errorf("get OCI policy: %w", err)
	}
	return response.Statements, deref(response.Etag), nil
}

func (c *sdkCloud) ReplacePolicyStatements(ctx context.Context, policyID, etag string, statements []string) error {
	if etag == "" {
		return errors.New("refusing an OCI policy update without an If-Match ETag")
	}
	request := identity.UpdatePolicyRequest{PolicyId: &policyID, IfMatch: &etag,
		UpdatePolicyDetails: identity.UpdatePolicyDetails{Statements: statements}}
	if _, err := c.identity.UpdatePolicy(ctx, request); err != nil {
		return fmt.Errorf("update OCI policy: %w", err)
	}
	return nil
}

func canonicalPrefix(v any) string {
	s, ok := v.(string)
	if !ok || len(s) > 128 {
		fail("bootstrap storage prefix is not canonical")
	}
	if s != "" {
		if strings.HasPrefix(s, "/") || strings.HasSuffix(s, "/") || strings.Contains(s, "//") {
			fail("bootstrap storage prefix is not canonical")
		}
		for segment := range strings.SplitSeq(s, "/") {
			if segment == "." || segment == ".." || !safeMatch(`[A-Za-z0-9][A-Za-z0-9._-]{0,127}`, segment) {
				fail("bootstrap storage prefix is not canonical")
			}
		}
	}
	return s
}

func storageStatements(plan, ids Object, prefix string, ledgerKey ...string) []string {
	identity, names, buckets := obj(plan["identity"]), obj(plan["preview_compartment_names"]), obj(plan["foundation_buckets"])
	dg, control := str(identity["controller_dynamic_group_name"]), str(names["control"])
	prefix = canonicalPrefix(prefix)
	r := []string{fmt.Sprintf("Allow dynamic-group %s to read objectstorage-namespaces in tenancy", dg)}
	for _, role := range []string{"ledger", "head", "backup", "material"} {
		r = append(r, fmt.Sprintf("Allow dynamic-group %s to read buckets in compartment %s where target.bucket.name='%s'", dg, control, str(buckets[role])))
	}
	for _, role := range []string{"ledger", "head"} {
		permissions := "request.permission='OBJECT_CREATE'"
		if role == "head" {
			permissions += ", request.permission='OBJECT_OVERWRITE'"
		}
		for _, version := range []string{"v1", "v2"} {
			name := "bootstrap/" + version + "/*"
			reserved := "bootstrap/v2/material-source/*"
			if prefix != "" {
				name = prefix + "/" + name
				reserved = prefix + "/" + reserved
			}
			exclusion := ""
			if version == "v2" {
				exclusion = fmt.Sprintf("target.object.name != /%s/, ", reserved)
			}
			r = append(r,
				fmt.Sprintf("Allow dynamic-group %s to manage objects in compartment %s where all {target.bucket.name='%s', target.object.name=/%s/, request.permission='OBJECT_READ'}", dg, control, str(buckets[role]), name),
				fmt.Sprintf("Allow dynamic-group %s to manage objects in compartment %s where all {target.bucket.name='%s', target.object.name=/%s/, %sany {%s}}", dg, control, str(buckets[role]), name, exclusion, permissions))
		}
	}
	// The leader keeps the configuration KV buckets in the versioned head
	// bucket (controller.kv_snapshot, docs/storage.md).
	r = append(r, fmt.Sprintf("Allow dynamic-group %s to manage objects in compartment %s where all {target.bucket.name='%s', target.object.name='kv-snapshot/v1/*', any {request.permission='OBJECT_READ', request.permission='OBJECT_CREATE', request.permission='OBJECT_OVERWRITE'}}", dg, control, str(buckets["head"])))
	// The leader follows the region's orchestrator release channel, which CI
	// writes, and reports its progress there (docs/continuous-delivery.md).
	r = append(r, fmt.Sprintf("Allow dynamic-group %s to manage objects in compartment %s where all {target.bucket.name='%s', target.object.name='releases/*', request.permission='OBJECT_READ'}", dg, control, str(buckets["head"])),
		fmt.Sprintf("Allow dynamic-group %s to manage objects in compartment %s where all {target.bucket.name='%s', target.object.name='releases/orchestrator/status.json', any {request.permission='OBJECT_CREATE', request.permission='OBJECT_OVERWRITE'}}", dg, control, str(buckets["head"])))
	// ... and each service release channel's report (TS-610), one statement
	// per role of internal/app's serviceReleaseRoles: OCI matches a * only
	// at the end of an object name, so services/*/status.json grants nothing.
	for _, role := range []string{"terrabase", "ts-auth"} {
		r = append(r, fmt.Sprintf("Allow dynamic-group %s to manage objects in compartment %s where all {target.bucket.name='%s', target.object.name='releases/services/%s/status.json', any {request.permission='OBJECT_CREATE', request.permission='OBJECT_OVERWRITE'}}", dg, control, str(buckets["head"]), role))
	}
	r = append(r, fmt.Sprintf("Allow dynamic-group %s to manage objects in compartment %s where all {target.bucket.name='%s', target.object.name='material/v2/*', any {request.permission='OBJECT_READ', request.permission='OBJECT_CREATE'}}", dg, control, str(buckets["material"])))
	keys := []string{str(ids["key"])}
	if len(ledgerKey) > 0 && ledgerKey[0] != keys[0] {
		keys = append(keys, ledgerKey[0])
	}
	for _, key := range keys {
		r = append(r, fmt.Sprintf("Allow dynamic-group %s to use keys in compartment %s where all {target.key.id='%s', any {request.permission='KEY_ENCRYPT', request.permission='KEY_DECRYPT'}}", dg, control, key), fmt.Sprintf("Allow dynamic-group %s to use key-delegate in compartment %s where target.key.id='%s'", dg, control, key))
	}
	return r
}
func controllerStatements(plan, ids Object, prefix string, ledgerKey ...string) []string {
	dg := str(obj(plan["identity"])["controller_dynamic_group_name"])
	names := obj(plan["preview_compartment_names"])
	r := []string{}
	for _, row := range [][3]string{{"manage", "instance-family", "control"}, {"manage", "instance-family", "workload"}, {"read", "instance-images", "control"}, {"use", "virtual-network-family", "network"}, {"use", "load-balancers", "network"}, {"manage", "volume-family", "control"}, {"manage", "volume-family", "workload"}} {
		r = append(r, fmt.Sprintf("Allow dynamic-group %s to %s %s in compartment %s", dg, row[0], row[1], str(names[row[2]])))
	}
	r = append(r, fmt.Sprintf("Allow dynamic-group %s to read secret-bundles in compartment %s where target.secret.name != /ts-bootstrap-source-*/", dg, str(names["control"])))
	return append(r, storageStatements(plan, ids, prefix, ledgerKey...)...)
}
func RequiredControllerStatements(plan, ids Object, prefix string) ([]string, error) {
	return capture(func() []string { return controllerStatements(plan, ids, prefix) })
}

func capture[T any](fn func() T) (v T, err error) {
	defer func() {
		if r := recover(); r != nil {
			if e, ok := r.(error); ok {
				err = e
			} else {
				err = fmt.Errorf("%v", r)
			}
		}
	}()
	return fn(), nil
}
